      transliteration = "Huwa at-tahuru ma'uhu al-hillu maytatuhu.",
      englishText = "A man asked the Messenger of Allah (ﷺ): 'O Messenger of Allah, we travel by sea and carry only a little fresh water with us; if we use it for ablution we will suffer thirst. May we perform ablution with seawater?' The Messenger of Allah (ﷺ) said: 'Its water is purifying and its dead (sea creatures) are lawful.'",
      urduText = "ایک شخص نے رسول اللہ ﷺ سے عرض کیا: یا رسول اللہ! ہم سمندری سفر کرتے ہیں اور اپنے ساتھ تھوڑا سا میٹھا پانی لے جاتے ہیں، اگر ہم اس سے وضو کریں تو پیاسے رہ جائیں گے، کیا ہم سمندر کے پانی سے وضو کر سکتے ہیں؟ رسول اللہ ﷺ نے فرمایا: سمندر کا پانی پاک کرنے والا ہے اور اس کا مردار (مچھلی وغیرہ) حلال ہے۔",
      narrator = "Abu Hurairah (RA)",
      grade = "Sahih",
      gradingScholar = "Ibn Hajar al-'Asqalani (Authenticated by Malik, ash-Shafi'i, al-Bukhari & at-Tirmidhi)",
      reference = "Bulugh al-Maram 1",
      linkedQuranVerses = "5:96, 25:48"
    ),

