      hadithNumber = 1,
      darussalamReference = "Shama'il Canonical: #1",
      inBookReference = "In-Book: Chapter 1, Hadith 1",
      arabicText = "كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْسَ بِالطَّوِيلِ الْبَائِنِ وَلَا بِالْقَصِيرِ، وَلَيْسَ بِالأَبْيَضِ الأَمْهَقِ وَلَا بِالآدَمِ، وَلَيْسَ بِالْجَعْدِ الْقَطَطِ وَلَا بِالسَّبِطِ، بَعَثَهُ اللَّهُ عَلَى رَأْسِ أَرْبَعِينَ سَنَةً",
      transliteration = "Kana Rasulullahi (ﷺ) laysa bit-tawilil-ba'ini wa la bil-qasir, wa laysa bil-abyadil-amhaqi wa la bil-adam, wa laysa bil-ja'dil-qatati wa la bis-sabit...",
      englishText = "Anas ibn Malik (RA) narrated: 'The Messenger of Allah (ﷺ) was neither conspicuously tall nor short; his complexion was neither chalky white nor dark brown (rather luminous white mixed with redness); and his hair was neither tightly curled nor completely straight (rather gently wavy). Allah commissioned him as a Messenger at the age of forty.'",
      urduText = "حضرت انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ ﷺ نہ بہت زیادہ دراز قد تھے اور نہ پست قد، نہ بالکل چونے کی طرح سفید تھے اور نہ گندمی مائل تیز سانولے (بلکہ سرخی مائل روشن و تابناک رنگت والے تھے)، اور آپ ﷺ کے مبارک بال نہ بالکل گھنگھریالے تھے اور نہ بالکل سیدھے۔ اللہ تعالیٰ نے چالیس برس کی عمر میں آپ ﷺ کو نبوت سے سرفراز فرمایا۔",
      narrator = "Anas ibn Malik (RA)",
      grade = "Sahih",
      gradingScholar = "Imam at-Tirmidhi (Agreed upon in Bukhari & Muslim)",
      reference = "Ash-Shama'il al-Muhammadiyyah 1",
      linkedQuranVerses = "33:21, 68:4"
    ),

