      arabicText = "لَمَّا قَضَى اللَّهُ الْخَلْقَ كَتَبَ فِي كِتَابِهِ فَهُوَ عِنْدَهُ فَوْقَ الْعَرْشِ إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي",
      transliteration = "Lamma qadallahul-khalqa kataba fi kitabihi fahuwa 'indahu fawqal-'Arshi: Inna rahmati ghalabat ghadabi.",
      englishText = "The Messenger of Allah (ﷺ) said: 'When Allah decreed the Creation, He wrote in His Book which is with Him above the Throne: Indeed, My mercy prevails over My wrath.'",
