    // ==================== KITAB AL-KAFI (SHIA CANONICAL #1) ====================
    HadithEntity(
      collectionKey = "alkafi",
      collectionName = "Kitab al-Kafi (Al-Kulayni)",
      bookNumber = 1,
      bookName = "Book 1: Intellect & Ignorance / Kitab al-'Aql wal-Jahl (كتاب العقل والجهل)",
      chapterNumber = 1,
      chapterName = "The Creation and Nobility of the Intellect",
      hadithNumber = 1,
      darussalamReference = "Al-Kafi Canonical: Usul Vol. 1, #1",
      inBookReference = "In-Book: Vol. 1, Book 1, Hadith 1",
      arabicText = "لَمَّا خَلَقَ اللَّهُ الْعَقْلَ اسْتَنْطَقَهُ ثُمَّ قَالَ لَهُ: أَقْبِلْ فَأَقْبَلَ، ثُمَّ قَالَ لَهُ: أَدْبِرْ فَأَدْبَرَ، ثُمَّ قَالَ: وَعِزَّتِي وَجَلَالِي مَا خَلَقْتُ خَلْقًا هُوَ أَحَبُّ إِلَيَّ مِنْكَ... بِكَ أُعَاقِبُ وَبِكَ أُثِيبُ",
      transliteration = "Lamma khalaqallahul-'aqla istantaqahu thumma qala lahu: Aqbil fa-aqbala, thumma qala lahu: Adbir fa-adbara... Bika u'aqibu wa bika uthib.",
      englishText = "Imam Abu Ja'far Muhammad al-Baqir (AS) narrated: 'When Allah created the Intellect (al-'Aql), He examined it and said to it: Come forward, so it came forward. Then He said to it: Go back, so it went back. Then He said: By My Might and Majesty, I have not created any creation dearer to Me than you; I only perfected you in those whom I love. Through you I command, through you I forbid, through you I hold accountable, and through you I reward.'",
      urduText = "امام ابو جعفر محمد الباقر علیہ السلام سے روایت ہے: جب اللہ تعالیٰ نے عقل کو پیدا فرمایا تو اس سے کلام فرمایا اور کہا: آگے بڑھ، تو وہ آگے بڑھی، پھر فرمایا: پیچھے ہٹ، تو وہ پیچھے ہٹ گئی۔ پھر اللہ تعالیٰ نے فرمایا: میری عزت و جلال کی قسم! میں نے کوئی ایسی مخلوق پیدا نہیں کی جو مجھے تجھ سے زیادہ محبوب ہو... تیرے ہی ذریعے میں ثواب دیتا ہوں اور تیرے ہی ذریعے مواخذہ کرتا ہوں۔",
      narrator = "Imam Muhammad al-Baqir (AS)",
      grade = "Mu'tabar (Canonical Opening Narration of Al-Kafi)",
      gradingScholar = "Shaykh al-Kulayni & 'Allamah al-Majlisi (Mir'at al-'Uqul)",
      reference = "Al-Kafi Vol. 1, Book 1, Hadith 1",
      linkedQuranVerses = "2:269, 39:9"
    ),
    HadithEntity(
      collectionKey = "alkafi",
      collectionName = "Kitab al-Kafi (Al-Kulayni)",
      bookNumber = 1,
      bookName = "Book 1: Intellect & Ignorance / Kitab al-'Aql wal-Jahl (كتاب العقل والجهل)",
      chapterNumber = 1,
      chapterName = "The Proof of Allah Upon Servants is the Intellect",
      hadithNumber = 5,
      darussalamReference = "Al-Kafi Canonical: Usul Vol. 1, #5",
      inBookReference = "In-Book: Vol. 1, Book 1, Hadith 5",
      arabicText = "مَا قَسَمَ اللَّهُ لِلْعِبَادِ شَيْئًا أَفْضَلَ مِنَ الْعَقْلِ، فَنَوْمُ الْعَاقِلِ أَفْضَلُ مِنْ سَهَرِ الْجَاهِلِ",
      transliteration = "Ma qasamallahu lil-'ibadi shay'an afdala minal-'aql, fa-nawmul-'aqili afdalu min saharil-jahil.",
      englishText = "Imam Ja'far as-Sadiq (AS) said: 'Allah has not distributed among His servants anything more virtuous than the intellect; the sleep of the person of intellect is more virtuous than the night-vigil of the ignorant.'",
