      arabicText = "خَلَقَ اللَّهُ الْمَاءَ طَهُورًا لَا يُنَجِّسُهُ شَيْءٌ إِلَّا مَا غَيَّرَ لَوْنَهُ أَوْ طَعْمَهُ أَوْ رِيحَهُ",
