      inBookReference = "In-Book: Book 1 (Sermons / Khutab), Sermon 1",
      arabicNumber = 1,
      arabicText = "الْحَمْدُ لِلَّهِ الَّذِي لَا يَبْلُغُ مِدْحَتَهُ الْقَائِلُونَ، وَلَا يُحْصِي نَعْمَاءَهُ الْعَادُّونَ، وَلَا يُؤَدِّي حَقَّهُ الْمُجْتَهِدُونَ، الَّذِي لَا يُدْرِكُهُ بُعْدُ الْهِمَمِ، وَلَا يَنَالُهُ غَوْصُ الْفِطَنِ",
      transliteration = "Al-hamdu lillahil-ladhi la yablughu midhatahul-qa'ilun, wa la yuhsi na'ma'ahul-'addun, wa la yu'addi haqqahul-mujtahidun...",
      englishText = "Sermon 1 (Creation of the Universe): Praise is due to Allah whose worth cannot be fully described by speakers, whose bounties cannot be counted by calculators, and whose rightful claim cannot be discharged by those who strive to do so; Whom the height of intellectual aspiration cannot encompass, and the diving of acute understanding cannot fathom.",
      urduText = "خطبہ 1 (توحید اور تخلیقِ کائنات): تمام تعریفیں اس اللہ کے لیے ہیں جس کی ثنا کی انتہا تک بولنے والوں کی رسائی نہیں ہو سکتی، اور جس کی نعمتوں کو گننے والے شمار نہیں کر سکتے، اور جس کا حق کوشش کرنے والے ادا نہیں کر سکتے؛ جسے بلند ہمتوں کی پرواز پا نہیں سکتی اور جس کی گہرائی تک زیرک عقلوں کی غوطہ زنی پہنچ نہیں سکتی۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) — Compiled by ash-Sharif ar-Radi",
      grade = "Classical Literary & Theological Masterpiece",
      gradingScholar = "Ash-Sharif ar-Radi & Ibn Abi al-Hadid (Subhi as-Salih #1)",
      reference = "Nahj al-Balagha, Sermon 1",
      linkedQuranVerses = "16:18, 42:11, 6:103"
    ),
    HadithEntity(
