      collectionName = "Nahj al-Balagha",
      bookNumber = 1,
      bookName = "Book 1: Sermons / Al-Khutab (باب الخطب)",
      chapterNumber = 3,
      chapterName = "Sermon 3: Khutbah ash-Shiqshiqiyyah (Patience & Stewardship of the Ummah)",
      hadithNumber = 3,
      darussalamReference = "Subhi as-Salih Edition: Sermon #3",
      inBookReference = "In-Book: Book 1 (Sermons / Khutab), Sermon 3 (Ash-Shiqshiqiyyah)",
      arabicNumber = 3,
      arabicText = "فَرَأَيْتُ أَنَّ الصَّبْرَ عَلَى هَاتَا أَحْجَى، فَصَبَرْتُ وَفِي الْعَيْنِ قَذًى، وَفِي الْحَلْقِ شَجًا... أَمَا وَاللَّهِ لَقَدْ تَقَمَّصَهَا فُلَانٌ",
      transliteration = "Fa-ra'aytu annas-sabra 'ala hata ahja, fa-sabartu wa fil-'ayni qadhan, wa fil-halqi shajan...",
      englishText = "Sermon 3 (Khutbah ash-Shiqshiqiyyah): Then I reflected and saw that endurance and patience over this matter was wiser; so I endured with patience while there was a mote in the eye and suffocation in the throat, preserving the unity of the Muslim community and upholding justice when the covenant of Allah taken from scholars was invoked not to remain silent over the gluttony of the oppressor and the hunger of the oppressed.",
      urduText = "خطبہ 3 (خطبہ شقشقیہ): پس میں نے غور کیا تو دیکھا کہ اس حال میں صبر و تحمل کرنا ہی عقل و حکمت کے زیادہ قریب ہے، چنانچہ میں نے صبر کیا اس حال میں کہ آنکھ میں تنکا کھٹک رہا تھا اور گلے میں پھندا اٹکا ہوا تھا، اور علما سے لیے گئے اللہ کے اس عہد کو یاد رکھا کہ وہ ظالم کی شکم سیری اور مظلوم کی گرسنگی پر خاموش نہ بیٹھیں۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) — Compiled by ash-Sharif ar-Radi",
      grade = "Canonical Sermon in Nahj al-Balagha",
      gradingScholar = "Ash-Sharif ar-Radi & Classical Commentators (Subhi as-Salih #3)",
      reference = "Nahj al-Balagha, Sermon 3",
      linkedQuranVerses = "3:187, 12:18"
    ),
    HadithEntity(
      collectionKey = "nahjulbalagha",
      collectionName = "Nahj al-Balagha",
      bookNumber = 1,
      bookName = "Book 1: Sermons / Al-Khutab (باب الخطب)",
      chapterNumber = 87,
      chapterName = "Sermon 87: Al-Khutbah al-Gharra' (Servants of Allah & Taqwa)",
