      darussalamReference = "Subhi as-Salih Edition: Sermon #87",
      inBookReference = "In-Book: Book 1 (Sermons / Khutab), Sermon 87 (Al-Gharra')",
      arabicNumber = 87,
      arabicText = "عِبَادَ اللَّهِ! إِنَّ أَنْصَحَ النَّاسِ لِنَفْسِهِ أَطْوَعُهُمْ لِرَبِّهِ، وَإِنَّ أَغَشَّهُمْ لِنَفْسِهِ أَعْصَاهُمْ لِرَبِّهِ",
      transliteration = "'Ibadallah! Inna ansahan-nasi li-nafsihi atwa'uhum li-Rabbihi, wa inna aghashshahum li-nafsihi a'sahum li-Rabbihi.",
      englishText = "Sermon 87 (Al-Khutbah al-Gharra'): O servants of Allah! Indeed, the most sincere person toward his own soul is the one most obedient to his Lord, and the most deceitful toward his own soul is the one most disobedient to his Lord. He who obeys Allah is safe and rejoices, while he who disobeys Him is disappointed and regrets.",
      urduText = "خطبہ 87 (خطبہ غراء): اے اللہ کے بندو! بے شک اپنے نفس کا سب سے بڑا خیر خواہ وہ شخص ہے جو اپنے رب کا سب سے زیادہ فرمانبردار ہو، اور اپنے نفس کے ساتھ سب سے زیادہ دھوکہ کرنے والا وہ ہے جو اپنے رب کا نافرمان ہو۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) — Compiled by ash-Sharif ar-Radi",
      grade = "Canonical Sermon in Nahj al-Balagha",
      gradingScholar = "Ash-Sharif ar-Radi (Subhi as-Salih #87)",
      reference = "Nahj al-Balagha, Sermon 87",
      linkedQuranVerses = "3:102, 59:18"
    ),
    HadithEntity(
      collectionKey = "nahjulbalagha",
      collectionName = "Nahj al-Balagha",
