      arabicText = "وَلَقَدْ كَانَ فِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ كَافٍ لَكَ فِي الْأُسْوَةِ، وَدَلِيلٌ لَكَ عَلَى ذَمِّ الدُّنْيَا وَعَيْبِهَا",
