      englishText = "Sermon 160 (The Prophetic Example): Certainly, in the Messenger of Allah (ﷺ) there is a sufficient model (uswah) for you, and a clear proof concerning the transient defects of this world, for its sides were constricted from him while its adornments were spread out for others, yet he detached his heart from its excess.",
