      inBookReference = "In-Book: Book 1 (Sermons / Khutab), Sermon 192 (Al-Qasi'ah)",
      arabicNumber = 192,
      arabicText = "الْحَمْدُ لِلَّهِ الَّذِي لَبِسَ الْعِزَّ وَالْكِبْرِيَاءَ، وَاخْتَارَهُمَا لِنَفْسِهِ دُونَ خَلْقِهِ، وَجَعَلَهُمَا حِمًى وَحَرَمًا عَلَى غَيْرِهِ",
      transliteration = "Al-hamdu lillahil-ladhi labisal-'izza wal-kibriya', wakhtarahuma li-nafsihi duna khalqih...",
      englishText = "Sermon 192 (Al-Khutbah al-Qasi'ah — The Disparaging Sermon against Pride): Praise be to Allah Who has donned the mantle of Might and Majesty and chosen them exclusively for Himself rather than His creation. Take warning from what Allah did to Iblis when he grew arrogant over Adam for a single moment and boasted of his origin.",
      urduText = "خطبہ 192 (خطبہ قاصعہ — تکبر اور عصبیت کی مذمت): تمام تعریفیں اس اللہ کے لیے ہیں جس نے عزت اور کبریائی کو اپنی ردا بنایا اور انہیں اپنی مخلوق کے بجائے اپنی ذات کے لیے خاص فرمایا۔ پس ابلیس کے انجام سے عبرت حاصل کرو جب اس نے تکبر کیا۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) — Compiled by ash-Sharif ar-Radi",
      grade = "Longest Canonical Sermon in Nahj al-Balagha",
      gradingScholar = "Ash-Sharif ar-Radi (Subhi as-Salih #192)",
      reference = "Nahj al-Balagha, Sermon 192",
      linkedQuranVerses = "7:12, 38:76, 49:13"
    ),
    HadithEntity(
      collectionKey = "nahjulbalagha",
      collectionName = "Nahj al-Balagha",
      bookNumber = 1,
      bookName = "Book 1: Sermons / Al-Khutab (باب الخطب)",
      chapterNumber = 193,
      chapterName = "Sermon 193: Khutbat al-Muttaqin / Sermon of Hammam (Qualities of the God-Conscious)",
      hadithNumber = 193,
      darussalamReference = "Subhi as-Salih Edition: Sermon #193",
      inBookReference = "In-Book: Book 1 (Sermons / Khutab), Sermon 193 (Khutbat al-Muttaqin / Hammam)",
      arabicNumber = 193,
      arabicText = "فَالْمُتَّقُونَ فِيهَا هُمْ أَهْلُ الْفَضَائِلِ: مَنْطِقُهُمُ الصَّوَابُ، وَمَلْبَسُهُمُ الِاقْتِصَادُ، وَمَشْيُهُمُ التَّوَاضُعُ، غَضُّوا أَبْصَارَهُمْ عَمَّا حَرَّمَ اللَّهُ عَلَيْهِمْ، وَوَقَفُوا أَسْمَاعَهُمْ عَلَى الْعِلْمِ النَّافِعِ لَهُمْ",
      transliteration = "Fal-muttaquna fiha hum ahlul-fada'il: mantiquhumus-sawab, wa malbasuhumul-iqtisad, wa mashyuhumut-tawadu', ghaddu absarahum 'amma harramallahu 'alayhim, wa waqafu asma'ahum 'alal-'ilmin-nafi'i lahum.",
      englishText = "Sermon 193 (Khutbat al-Muttaqin — Sermon of Hammam on the God-Conscious): Thus the God-conscious (al-Muttaqun) in this world are the people of excellence: their speech is truthful and upright, their dress is moderate, and their walk is humble. They lower their gaze from what Allah has forbidden to them, and they dedicate their hearing to beneficial knowledge. During the night they stand upon their feet reading portions of the Qur'an with contemplation.",
      urduText = "خطبہ 193 (خطبہ متقین / خطبہ ہمام): پس متقین اس دنیا میں فضائل و کمالات کے حامل ہیں: ان کی گفتگو راست و درست ہوتی ہے، ان کا لباس میانہ روی پر مبنی ہوتا ہے، اور ان کی چال میں تواضع و انکساری ہوتی ہے۔ انہوں نے اپنی نگاہوں کو اللہ کی حرام کردہ چیزوں سے جھکا رکھا ہے اور اپنے کانوں کو نفع بخش علم کے لیے وقف کر رکھا ہے۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) to Hammam — Compiled by ash-Sharif ar-Radi",
      grade = "Famous Canonical Sermon (Also in Al-Kafi Vol. 2 & Bihar al-Anwar)",
      gradingScholar = "Ash-Sharif ar-Radi & Shaykh al-Kulayni (Subhi as-Salih #193)",
      reference = "Nahj al-Balagha, Sermon 193",
      linkedQuranVerses = "2:2, 3:133, 25:63, 51:17"
    ),
    HadithEntity(
      collectionKey = "nahjulbalagha",
      collectionName = "Nahj al-Balagha",
      bookNumber = 2,
      bookName = "Book 2: Letters & Epistles / Al-Kutub (باب الكتب والرسائل)",
      chapterNumber = 31,
      chapterName = "Letter 31: Ethical & Spiritual Counsel to Imam al-Hasan (AS) at Hadirin",
      hadithNumber = 31,
      darussalamReference = "Subhi as-Salih Edition: Letter #31",
      inBookReference = "In-Book: Book 2 (Letters / Makatib), Letter 31",
      arabicNumber = 31,
      arabicText = "أَحْيِ قَلْبَكَ بِالْمَوْعِظَةِ، وَأَمِتْهُ بِالزَّهَادَةِ، وَقَوِّهِ بِالْيَقِينِ، وَنَوِّرْهُ بِالْحِكْمَةِ، وَذَلِّلْهُ بِذِكْرِ الْمَوْتِ... وَاجْعَلْ نَفْسَكَ مِيزَانًا فِيمَا بَيْنَكَ وَبَيْنَ غَيْرِكَ، فَأَحْبِبْ لِغَيْرِكَ مَا تُحِبُّ لِنَفْسِكَ",
      transliteration = "Ahyi qalbaka bil-maw'izah, wa amithu biz-zahadah, wa qawwihi bil-yaqin, wa nawwirhu bil-hikmah... Waj'al nafsaka mizanan fima baynaka wa bayna ghayrika, fa-ahbib li-ghayrika ma tuhibbu li-nafsik.",
      englishText = "Letter 31 (Counsel to his son al-Hasan): Revive your heart with admonition, subdue its caprice with detachment, strengthen it with certainty, and illuminate it with wisdom... And make your own self a balance between you and others: love for others what you love for yourself, and dislike for them what you dislike for yourself.",
      urduText = "مکتوب 31 (فرزندِ ارجمند امام حسنؑ کے نام وصیت): اپنے دل کو نصیحت کے ذریعے زندہ رکھو، زہد کے ذریعے اس کی خواہشات کو قابو میں رکھو، یقین کے ذریعے اسے مضبوط بناؤ اور حکمت کے ذریعے اسے منور کرو... اور اپنے نفس کو اپنے اور دوسروں کے درمیان میزان بناؤ، پس دوسروں کے لیے وہی پسند کرو جو اپنے لیے پسند کرتے ہو۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) to al-Hasan ibn 'Ali",
      grade = "Verified Canonical Epistle",
      gradingScholar = "Ash-Sharif ar-Radi (Subhi as-Salih Letter #31)",
      reference = "Nahj al-Balagha, Letter 31",
      linkedQuranVerses = "31:13, 31:17, 83:1"
    ),
    HadithEntity(
      collectionKey = "nahjulbalagha",
      collectionName = "Nahj al-Balagha",
      bookNumber = 2,
      bookName = "Book 2: Letters & Epistles / Al-Kutub (باب الكتب والرسائل)",
      chapterNumber = 47,
      chapterName = "Letter 47: Final Will to Al-Hasan and Al-Husayn on Taqwa, the Quran & Orphans",
      hadithNumber = 47,
      darussalamReference = "Subhi as-Salih Edition: Letter #47",
      inBookReference = "In-Book: Book 2 (Letters / Makatib), Letter 47",
      arabicNumber = 47,
      arabicText = "أُوصِيكُمَا بِتَقْوَى اللَّهِ، وَأَلَّا تَبْغِيَا الدُّنْيَا وَإِنْ بَغَتْكُمَا... اللَّهَ اللَّهَ فِي الْأَيْتَامِ، فَلَا تُغِبُّوا أَفْوَاهَهُمْ... وَاللَّهَ اللَّهَ فِي الْقُرْآنِ، لَا يَسْبِقُكُمْ بِالْعَمَلِ بِهِ غَيْرُكُمْ، وَاللَّهَ اللَّهَ فِي الصَّلَاةِ فَإِنَّهَا عَمُودُ دِينِكُمْ",
      transliteration = "Usikuma bi-taqwallah, wa alla tabghiyad-dunya wa in baghatkuma... Allaha Allaha fil-aytam... Wallaha Allaha fil-Qur'an, la yasbiqukum bil-'amali bihi ghayrukum, wallaha Allaha fis-salati fa-innaha 'amudu dinikum.",
      englishText = "Letter 47 (Final Will to Al-Hasan & Al-Husayn): I advise you both to hold fast to Taqwa (God-consciousness)... Fear Allah, fear Allah regarding orphans! Fear Allah, fear Allah regarding your neighbors! Fear Allah, fear Allah regarding the Qur'an, lest others surpass you in acting upon it! And fear Allah, fear Allah regarding the Prayer (Salah), for it is the pillar of your religion!",
      urduText = "مکتوب 47 (امام حسنؑ و امام حسینؑ کے نام آخری وصیت): میں تم دونوں کو تقویٰ الٰہی کی وصیت کرتا ہوں... یتیموں کے معاملے میں اللہ سے ڈرو، پڑوسیوں کے معاملے میں اللہ سے ڈرو، قرآن کے معاملے میں اللہ سے ڈرو کہ کہیں دوسرے اس پر عمل کرنے میں تم سے سبقت نہ لے جائیں، اور نماز کے معاملے میں اللہ سے ڈرو کیونکہ وہ تمہارے دین کا ستون ہے۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) to al-Hasan and al-Husayn",
      grade = "Mutawatir Historical Testament",
      gradingScholar = "Ash-Sharif ar-Radi (Subhi as-Salih Letter #47)",
      reference = "Nahj al-Balagha, Letter 47",
      linkedQuranVerses = "4:36, 93:9, 2:238"
    ),
    HadithEntity(
      collectionKey = "nahjulbalagha",
      collectionName = "Nahj al-Balagha",
      bookNumber = 2,
      bookName = "Book 2: Letters & Epistles / Al-Kutub (باب الكتب والرسائل)",
      chapterNumber = 53,
      chapterName = "Letter 53: Covenant of Governance to Malik al-Ashtar",
      hadithNumber = 53,
      darussalamReference = "Subhi as-Salih Edition: Letter #53",
      inBookReference = "In-Book: Book 2 (Letters / Makatib), Letter 53",
      arabicNumber = 53,
      arabicText = "أَشْعِرْ قَلْبَكَ الرَّحْمَةَ لِلرَّعِيَّةِ، وَالْمَحَبَّةَ لَهُمْ، وَاللُّطْفَ بِهِمْ... فَإِنَّهُمْ صِنْفَانِ: إِمَّا أَخٌ لَكَ فِي الدِّينِ، وَإِمَّا نَظِيرٌ لَكَ فِي الْخَلْقِ",
      transliteration = "Ash'ir qalbakar-rahmata lir-ra'iyyati, wal-mahabbata lahum, wal-lutfa bihim... Fa-innahum sinfani: imma akhun laka fid-din, wa imma nazirun laka fil-khalq.",
      englishText = "Letter 53 (Charter to Malik al-Ashtar): Infuse your heart with mercy for the people under your governance, love for them, and kindness towards them... For they are of two kinds: either your brother in religion or your equal in creation.",
      urduText = "مکتوب 53 (عہد نامہ مالک اشتر): اپنے دل میں رعایا کے لیے رحمت، محبت اور نرمی پیدا کرو... کیونکہ لوگ دو ہی قسم کے ہیں: یا تو وہ دین میں تمہارے بھائی ہیں یا خلقت (انسانیت) میں تمہاری مثل ہیں۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) to Malik al-Ashtar",
      grade = "Verified Historical Epistle",
      gradingScholar = "Ash-Sharif ar-Radi (Subhi as-Salih Letter #53)",
      reference = "Nahj al-Balagha, Letter 53",
      linkedQuranVerses = "4:58, 16:90, 49:13"
    ),
    HadithEntity(
      collectionKey = "nahjulbalagha",
      collectionName = "Nahj al-Balagha",
      bookNumber = 3,
      bookName = "Book 3: Sayings & Maxims / Al-Hikam (باب الحكم والمواعظ)",
      chapterNumber = 82,
      chapterName = "Saying 82: Five Gems of Wisdom Worth Travelling For",
      hadithNumber = 82,
      darussalamReference = "Subhi as-Salih Edition: Saying (Hikmah) #82",
      inBookReference = "In-Book: Book 3 (Sayings / Hikam), Saying 82",
      arabicNumber = 82,
      arabicText = "لَا يَرْجُوَنَّ عَبْدٌ إِلَّا رَبَّهُ، وَلَا يَخَافَنَّ إِلَّا ذَنْبَهُ، وَلَا يَسْتَحِيَنَّ عَالِمٌ إِذَا سُئِلَ عَمَّا لَا يَعْلَمُ أَنْ يَقُولَ: اللَّهُ أَعْلَمُ، وَاعْلَمُوا أَنَّ الصَّبْرَ مِنَ الْإِيمَانِ بِمَنْزِلَةِ الرَّأْسِ مِنَ الْجَسَدِ",
      transliteration = "La yarjuwanna 'abdun illa Rabbahu, wa la yakhafanna illa dhanbahu, wa la yastahiyanna 'alimun idha su'ila 'amma la ya'lamu an yaqula: Allahu a'lam; wa'lamu annas-sabra minal-imani bi-manzilatir-ra'si minal-jasad.",
      englishText = "Saying 82 (Hikmah 82): Let no servant place his hope in anyone except his Lord; let him not fear anything except his own sin; let not the ignorant be ashamed to ask until he learns; let not the scholar, when asked about what he does not know, be ashamed to say 'Allah knows best'; and know that patience in relation to faith is like the head in relation to the body.",
      urduText = "حکمت 82: بندے کو چاہیے کہ وہ اپنے رب کے سوا کسی سے امید نہ رکھے، اپنے گناہ کے سوا کسی چیز سے نہ ڈرے، جو شخص نہ جانتا ہو وہ سیکھنے میں شرم نہ کرے، اور جب عالم سے ایسی بات پوچھی جائے جو وہ نہ جانتا ہو تو 'اللہ اعلم' کہنے میں ہچکچاہٹ محسوس نہ کرے؛ اور جان لو کہ ایمان میں صبر کی منزلت وہی ہے جو جسم میں سر کی ہے۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) — Compiled by ash-Sharif ar-Radi",
      grade = "Canonical Maxim (Hikmah)",
      gradingScholar = "Ash-Sharif ar-Radi (Subhi as-Salih Saying #82)",
      reference = "Nahj al-Balagha, Saying 82",
      linkedQuranVerses = "2:153, 94:8"
    ),
    HadithEntity(
      collectionKey = "nahjulbalagha",
      collectionName = "Nahj al-Balagha",
      bookNumber = 3,
      bookName = "Book 3: Sayings & Maxims / Al-Hikam (باب الحكم والمواعظ)",
      chapterNumber = 147,
      chapterName = "Saying 147: Discourse to Kumayl ibn Ziyad on Knowledge & Hearts",
      hadithNumber = 147,
      darussalamReference = "Subhi as-Salih Edition: Saying (Hikmah) #147",
      inBookReference = "In-Book: Book 3 (Sayings / Hikam), Saying 147 (Hadith Kumayl)",
      arabicNumber = 147,
      arabicText = "يَا كُمَيْلُ بْنَ زِيَادٍ! إِنَّ هَذِهِ الْقُلُوبَ أَوْعِيَةٌ فَخَيْرُهَا أَوْعَاهَا... النَّاسُ ثَلَاثَةٌ: فَعَالِمٌ رَبَّانِيٌّ، وَمُتَعَلِّمٌ عَلَى سَبِيلِ نَجَاةٍ، وَهَمَجٌ رَعَاعٌ... الْعِلْمُ خَيْرٌ مِنَ الْمَالِ؛ الْعِلْمُ يَحْرُسُكَ وَأَنْتَ تَحْرُسُ الْمَالَ",
      transliteration = "Ya Kumaylu bna Ziyad! Inna hadhihil-quluba aw'iyatun fa-khayruha aw'aha... Al-'ilmu khayrun minal-mal; al-'ilmu yahrusuka wa anta tahrusul-mal.",
      englishText = "Saying 147 (Discourse to Kumayl ibn Ziyad): O Kumayl ibn Ziyad! Indeed these hearts are vessels, and the best of them is that which retains the most good... People are of three types: a godly scholar ('alim rabbani), a seeker of knowledge on the path of salvation, and aimless followers of every caller. Knowledge is better than wealth: knowledge guards you, whereas you must guard wealth; wealth diminishes when spent, whereas knowledge increases when shared.",
      urduText = "حکمت 147 (حدیثِ کمیل بن زیاد): اے کمیل بن زیاد! بے شک یہ دل ظروف (برتن) ہیں اور ان میں بہترین وہ ہے جو سب سے زیادہ خیر کو محفوظ رکھنے والا ہو... لوگ تین قسم کے ہیں: عالمِ ربانی، راہِ نجات پر گامزن طالبِ علم، اور ہر پکارنے والے کے پیچھے چلنے والے۔ علم مال سے بہتر ہے کیونکہ علم تمہاری حفاظت کرتا ہے جبکہ مال کی تمہیں حفاظت کرنی پڑتی ہے۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) to Kumayl ibn Ziyad an-Nakha'i",
      grade = "Famous Canonical Wisdom Narration",
      gradingScholar = "Ash-Sharif ar-Radi & Ibn 'Abd al-Barr (Subhi as-Salih Saying #147)",
      reference = "Nahj al-Balagha, Saying 147",
      linkedQuranVerses = "35:28, 39:9, 58:11"
    ),
    HadithEntity(
      collectionKey = "nahjulbalagha",
      collectionName = "Nahj al-Balagha",
      bookNumber = 3,
      bookName = "Book 3: Sayings & Maxims / Al-Hikam (باب الحكم والمواعظ)",
      chapterNumber = 480,
      chapterName = "Saying 480: A Person's Worth Is the Good He Excels In",
      hadithNumber = 480,
      darussalamReference = "Subhi as-Salih Edition: Saying (Hikmah) #81 / #480",
      inBookReference = "In-Book: Book 3 (Sayings / Hikam), Saying 81 & 480",
      arabicNumber = 480,
      arabicText = "قِيمَةُ كُلِّ امْرِئٍ مَا يُحْسِنُهُ، وَتَكَلَّمُوا تُعْرَفُوا فَإِنَّ الْمَرْءَ مَخْبُوءٌ تَحْتَ لِسَانِهِ",
      transliteration = "Qimatu kulli imri'in ma yuhsinuhu; wa takallamu tu'rafu fa-innal-mar'a makhbu'un tahta lisanih.",
      englishText = "Saying 480 (Hikmah): The worth of every person is the good that he excels in; and speak so that you may be known, for indeed a person is hidden beneath his tongue.",
      urduText = "حکمت 480: ہر انسان کی قدر و قیمت وہ اچھائی اور کمال ہے جسے وہ بہترین طریقے سے انجام دیتا ہے؛ اور گفتگو کرو تاکہ پہچانے جاؤ کیونکہ انسان اپنی زبان کے نیچے پوشیدہ ہوتا ہے۔",
      narrator = "'Ali ibn Abi Talib (RA / AS) — Compiled by ash-Sharif ar-Radi",
      grade = "Canonical Maxim (Hikmah)",
      gradingScholar = "Ash-Sharif ar-Radi (Subhi as-Salih Hikam)",
      reference = "Nahj al-Balagha, Saying 480",
      linkedQuranVerses = "17:53, 33:70"
    ),

    // ==================== BIHAR AL-ANWAR ====================
    HadithEntity(
      collectionKey = "bihar",
      collectionName = "Bihar al-Anwar",
      bookNumber = 1,
      bookName = "Volume 1: Book of Knowledge / Kitab al-'Ilm (كتاب العلم)",
      chapterNumber = 1,
      chapterName = "The Four Categories Regarding Knowledge",
      hadithNumber = 1,
      darussalamReference = "Al-Wafa' Edition: Vol. 1, Bab 1, #1",
      inBookReference = "In-Book: Vol. 1, Chapter 1, Hadith 1",
      arabicNumber = 1,
      arabicText = "كُنْ عَالِمًا أَوْ مُتَعَلِّمًا أَوْ مُسْتَمِعًا أَوْ مُحِبًّا وَلَا تَكُنِ الْخَامِسَ فَتَهْلِكَ",
      transliteration = "Kun 'aliman aw muta'alliman aw mustami'an aw muhibban, wa la takunil-khamisa fa-tahlika.",
