      arabicText = "الْخَلْقُ عِيَالُ اللَّهِ، فَأَحَبُّ الْخَلْقِ إِلَى اللَّهِ مَنْ نَفَعَ عِيَالَ اللَّهِ وَأَدْخَلَ عَلَى أَهْلِ بَيْتٍ سُرُورًا",
