      urduText = "حافظ ابن حجر رحمہ اللہ فتح الباری (1/9) میں اور امام نووی شرح صحیح مسلم میں فرماتے ہیں کہ علما کا حدیثِ نیت کی عظمت پر اتفاق ہے اور یہ ان بنیادی احادیث میں سے ہے جن پر اسلام کا مدار ہے۔",
