      hadithNumber = 1,
      darussalamReference = "Al-Sahifa al-Sajjadiyya: Supplication #1",
      inBookReference = "In-Book: Du'a 1 (Tahmid Allah)",
      arabicNumber = 1,
      arabicText = "الْحَمْدُ لِلَّهِ الْأَوَّلِ بِلَا أَوَّلٍ كَانَ قَبْلَهُ، وَالْآخِرِ بِلَا آخِرٍ يَكُونُ بَعْدَهُ، الَّذِي قَصُرَتْ عَنْ رُؤْيَتِهِ أَبْصَارُ النَّاظِرِينَ، وَعَجَزَتْ عَنْ نَعْتِهِ أَوْهَامُ الْوَاصِفِينَ",
      transliteration = "Al-hamdu lillahil-Awwali bila awwalin kana qablahu, wal-Akhiri bila akhirin yakunu ba'dahu, alladhi qasurat 'an ru'yatihi absarun-nazirin...",
      englishText = "Supplication 1 (Praise of Allah): Praise belongs to Allah, the First without any first before Him, and the Last without any last after Him; Whom the beholders' eyes fall short of seeing, and the imaginations of describers are incapable of depicting.",
      urduText = "دعائے اول (حمدِ الٰہی): تمام تعریفیں اس اللہ کے لیے ہیں جو اول ہے بغیر اس کے کہ اس سے پہلے کوئی اول رہا ہو، اور آخر ہے بغیر اس کے کہ اس کے بعد کوئی آخر ہو؛ جس کے دیدار سے دیکھنے والوں کی نگاہیں قاصر ہیں اور جس کی توصیف سے بیان کرنے والوں کے اوہام عاجز ہیں۔",
      narrator = "Imam 'Ali ibn al-Husayn Zayn al-'Abidin (AS)",
      grade = "Mutawatir Devotional Corpus",
      gradingScholar = "Shaykh al-Mufid & Classical Imami Consensus",
      reference = "Al-Sahifa al-Sajjadiyya, Supplication 1",
      linkedQuranVerses = "57:3, 6:103"
    ),
    HadithEntity(
      collectionKey = "sajjadiyya",
      collectionName = "Al-Sahifa al-Sajjadiyya",
      bookNumber = 1,
      bookName = "Supplication 1 & 20: Praise of Allah and Noble Moral Traits",
      chapterNumber = 20,
      chapterName = "Du'a Makarim al-Akhlaq (Supplication for Noble Character)",
      hadithNumber = 20,
      darussalamReference = "Al-Sahifa al-Sajjadiyya: Supplication #20",
      inBookReference = "In-Book: Du'a 20 (Makarim al-Akhlaq)",
      arabicNumber = 20,
      arabicText = "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَبَلِّغْ بِإِيمَانِي أَكْمَلَ الْإِيمَانِ، وَاجْعَلْ يَقِينِي أَفْضَلَ الْيَقِينِ، وَانْتَهِ بِنِيَّتِي إِلَى أَحْسَنِ النِّيَّاتِ، وَبِعَمَلِي إِلَى أَحْسَنِ الْأَعْمَالِ",
      transliteration = "Allahumma salli 'ala Muhammadin wa Alihi, wa balligh bi-imani akmalal-iman, waj'al yaqini afdalal-yaqin, wantahi bi-niyyati ila ahsanin-niyyat, wa bi-'amali ila ahsanil-a'mal.",
      englishText = "Supplication 20 (Du'a Makarim al-Akhlaq): O Allah, bless Muhammad and his Household, cause my faith to reach the most perfect faith, make my certainty the most excellent certainty, and carry my intention to the best of intentions and my deeds to the best of deeds.",
      urduText = "دعائے مکارم الاخلاق (دعا 20): اے اللہ! محمد اور آلِ محمد پر رحمت نازل فرما، اور میرے ایمان کو کامل ترین ایمان تک پہنچا دے، میرے یقین کو افضل ترین یقین بنا دے، اور میری نیت کو بہترین نیتوں اور میرے عمل کو بہترین اعمال تک پہنچا دے۔",
      narrator = "Imam 'Ali ibn al-Husayn Zayn al-'Abidin (AS)",
      grade = "Mutawatir Devotional Corpus",
      gradingScholar = "Shaykh al-Mufid & Classical Imami Consensus",
      reference = "Al-Sahifa al-Sajjadiyya, Supplication 20",
      linkedQuranVerses = "33:56, 68:4"
    ),
    HadithEntity(
      collectionKey = "sajjadiyya",
      collectionName = "Al-Sahifa al-Sajjadiyya",
      bookNumber = 1,
      bookName = "Supplication 24: For Parents (دعاؤه لأبويه عليهما السلام)",
      chapterNumber = 24,
      chapterName = "Du'a 24: Supplication for One's Parents",
      hadithNumber = 24,
      darussalamReference = "Al-Sahifa al-Sajjadiyya: Supplication #24",
      inBookReference = "In-Book: Du'a 24 (Supplication for Parents)",
      arabicNumber = 24,
      arabicText = "اللَّهُمَّ اجْعَلْنِي أَهَابُهُمَا هَيْبَةَ السُّلْطَانِ الْعَسُوفِ، وَأَبَرُّهُمَا بِرَّ الْأُمِّ الرَّؤُوفِ، وَاجْعَلْ طَاعَتِي لِوَالِدَيَّ وَبِرِّي بِهِمَا أَقَرَّ لِعَيْنِي مِنْ رَقْدَةِ الْوَسْنَانِ",
      transliteration = "Allahummaj'alni ahabuhuma haybatas-sultanil-'asuf, wa abarruhuma birral-ummir-ra'uf, waj'al ta'ati li-walidayya wa birri bihima aqarra li-'ayni min raqdatil-wasnan.",
      englishText = "Supplication 24 (For Parents): O Allah, make me revere them with deep respect, and be dutiful to them with the tenderness of a compassionate mother; and make my obedience and devotion to my parents more soothing to my eyes than sleep to the drowsy.",
      urduText = "دعائے والدین (دعا 24): اے اللہ! مجھے اپنے والدین کا بے حد ادب و احترام کرنے والا اور ایک شفیق ماں کی طرح ان کے ساتھ نیکی اور محبت کرنے والا بنا دے، اور والدین کی اطاعت و خدمت کو میری آنکھوں کی ٹھنڈک بنا دے۔",
      narrator = "Imam 'Ali ibn al-Husayn Zayn al-'Abidin (AS)",
      grade = "Mutawatir Devotional Corpus",
      gradingScholar = "Shaykh al-Mufid & Classical Imami Consensus",
      reference = "Al-Sahifa al-Sajjadiyya, Supplication 24",
      linkedQuranVerses = "17:23, 17:24, 31:14"
    ),

