      urduText = "اللہ عزوجل کا فرمان ہے: کلمہ لا الہ الا اللہ میرا قلعہ ہے، پس جو میرے قلعے میں داخل ہو گیا وہ میرے عذاب سے محفوظ ہو گیا۔",
