      arabicNumber = 2,
      arabicText = "الْعُبُودِيَّةُ جَوْهَرَةٌ كُنْهُهَا الرُّبُوبِيَّةُ، فَمَا فُقِدَ مِنَ الْعُبُودِيَّةِ وُجِدَ فِي الرُّبُوبِيَّةِ",
      transliteration = "Al-'ubudiyyatu jawharatun kunhuhar-rububiyyah, fama fuqida minal-'ubudiyyati wujida fir-rububiyyah.",
      englishText = "Imam Ja'far al-Sadiq (AS) said: 'Servitude ('Ubudiyyah) is a jewel whose innermost reality is realizing Divine Lordship (Rububiyyah); whatever a servant relinquishes in humble servitude is found through Allah's gracious care.'",
      urduText = "امام جعفر صادق علیہ السلام نے فرمایا: عبودیت (بندگی) ایک ایسا جوہر ہے جس کی حقیقت ربوبیت کی معرفت ہے؛ پس بندہ عاجزی اور بندگی میں جو کچھ اللہ کے سپرد کرتا ہے وہ ربوبیت کی عطا میں پا لیتا ہے۔",
      narrator = "Imam Ja'far al-Sadiq (AS)",
