    HadithEntity(
      collectionKey = "nasai_kubra",
      collectionName = "Al-Sunan al-Kubra (Imam al-Nasa'i)",
      bookNumber = 1,
      bookName = "Book 1: Kitab al-Taharah & Kitab al-'Ilm (كتاب الطهارة وكتاب العلم)",
      chapterNumber = 1,
      chapterName = "Excellence of Supplicating for Beneficial Knowledge",
      hadithNumber = 5839,
      darussalamReference = "Al-Risalah Kubra: #5839",
      inBookReference = "In-Book: Kitab al-'Ilm, Hadith 5839",
      arabicNumber = 5839,
      arabicText = "اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي وَعَلِّمْنِي مَا يَنْفَعُنِي وَزِدْنِي عِلْمًا",
      transliteration = "Allahummanfa'ni bima 'allamtani, wa 'allimni ma yanfa'uni, wa zidni 'ilman.",
      englishText = "The Messenger of Allah (ﷺ) used to supplicate: 'O Allah, benefit me through what You have taught me, teach me what will benefit me, and increase me in knowledge.'",
      urduText = "رسول اللہ ﷺ یہ دعا مانگا کرتے تھے: اے اللہ! جو علم تو نے مجھے عطا فرمایا ہے اسے میرے لیے نافع بنا دے، مجھے وہ علم سکھا جو میرے لیے فائدہ مند ہو، اور میرے علم میں اضافہ فرما۔",
      narrator = "Abu Hurairah (RA)",
      grade = "Sahih",
      gradingScholar = "Imam al-Nasa'i & Hasan Shalabi",
      reference = "Al-Sunan al-Kubra (Al-Nasa'i) 5839",
      linkedQuranVerses = "20:114"
    ),

    // ==================== AL-MU'JAM AL-KABIR (AL-TABARANI) ====================
    HadithEntity(
      collectionKey = "tabarani_kabir",
      collectionName = "Al-Mu'jam al-Kabir & Al-Awsat (Al-Tabarani)",
      bookNumber = 12,
      bookName = "Volume 12: Musnad 'Abdullah ibn 'Umar (مسند عبد الله بن عمر)",
      chapterNumber = 1,
      chapterName = "The Most Beloved People to Allah are the Most Beneficial to People",
      hadithNumber = 13646,
      darussalamReference = "Al-Salafi Mu'jam: #13646",
      inBookReference = "In-Book: Vol. 12, p. 453, Hadith 13646",
      arabicNumber = 13646,
      arabicText = "أَحَبُّ النَّاسِ إِلَى اللَّهِ أَنْفَعُهُمْ لِلنَّاسِ، وَأَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ عَزَّ وَجَلَّ سُرُورٌ تُدْخِلُهُ عَلَى مُسْلِمٍ، أَوْ تَكْشِفُ عَنْهُ كُرْبَةً، أَوْ تَقْضِي عَنْهُ دَيْنًا، أَوْ تَطْرُدُ عَنْهُ جُوعًا",
      transliteration = "Ahabbun-nasi ilallahi anfa'uhum lin-nas, wa ahabbul-a'mali ilallahi 'azza wa jalla sururun tudkhiluhu 'ala Muslimin, aw takshifu 'anhu kurbatan, aw taqdi 'anhu daynan, aw tatrudu 'anhu ju'an.",
      englishText = "The most beloved of people to Allah are those who are most beneficial to people; and the most beloved of deeds to Allah, Mighty and Majestic, is joy that you bring to a Muslim, or relieving him of distress, or paying off a debt for him, or dispelling his hunger.",
      urduText = "اللہ کے نزدیک سب سے محبوب انسان وہ ہے جو لوگوں کو سب سے زیادہ نفع پہنچانے والا ہو، اور اللہ عزوجل کے نزدیک محبوب ترین عمل یہ ہے کہ تم کسی مسلمان کے دل میں خوشی داخل کرو، یا اس کی کوئی مصیبت دور کرو، یا اس کا قرض ادا کرو، یا اس کی بھوک مٹاؤ۔",
      narrator = "'Abdullah ibn 'Umar (RA)",
      grade = "Hasan",
      gradingScholar = "Imam al-Mundhiri & Shaykh al-Albani (Al-Targhib)",
      reference = "Al-Mu'jam al-Kabir 13646",
      linkedQuranVerses = "5:2, 76:8, 76:9"
    ),

    // ==================== AL-KHISAL (SHAYKH AL-SADUQ) ====================
    HadithEntity(
      collectionKey = "khisal",
      collectionName = "Al-Khisal (Shaykh al-Saduq)",
      bookNumber = 1,
      bookName = "Book 1: Bab al-Thalathah (باب الثلاثة — Threefold Qualities)",
      chapterNumber = 1,
      chapterName = "Three Qualities By Which a Believer Attains the Good of This World and the Hereafter",
      hadithNumber = 1,
      darussalamReference = "Al-Khisal Canonical: Vol. 1, Bab 3, #1",
      inBookReference = "In-Book: Part 3 (Threefold Qualities), Hadith 1 • Thaqalayn API Ref",
      arabicNumber = 1,
      arabicText = "ثَلَاثٌ مَنْ كُنَّ فِيهِ اسْتَكْمَلَ خِصَالَ الْإِيمَانِ: الَّذِي إِذَا رَضِيَ لَمْ يُدْخِلْهُ رِضَاهُ فِي بَاطِلٍ، وَإِذَا غَضِبَ لَمْ يُخْرِجْهُ غَضَبُهُ مِنَ الْحَقِّ، وَإِذَا قَدِرَ لَمْ يَتَعَاطَ مَا لَيْسَ لَهُ بِحَقٍّ",
      transliteration = "Thalathun man kunna fihi istakmala khisalal-iman: alladhi idha radiya lam yudkhilhu ridahu fi batil, wa idha ghadiba lam yukhrijhu ghadabuhu minal-haqq, wa idha qadira lam yata'ata ma laysa lahu bi-haqq.",
      englishText = "Imam Ja'far al-Sadiq (AS) said: 'Whoever possesses three qualities has perfected the traits of faith: one whose pleasure does not lead him into falsehood, whose anger does not take him outside the truth, and who, when given power, does not take what is not rightfully his.'",
      urduText = "امام جعفر صادق علیہ السلام نے فرمایا: جس شخص میں تین خصلتیں ہوں اس نے ایمان کی صفات کو مکمل کر لیا: وہ شخص جس کی خوشنودی اسے باطل میں داخل نہ کرے، جس کا غصہ اسے حق سے باہر نہ نکالے، اور جب اسے قدرت و اختیار ملے تو وہ ایسی چیز نہ لے جس کا وہ حق دار نہیں۔",
      narrator = "Imam Ja'far ibn Muhammad al-Sadiq (AS)",
      grade = "Mu'tabar (Imami Rijal Grading)",
      gradingScholar = "Shaykh al-Saduq Ibn Babawayh (Al-Khisal)",
      reference = "Al-Khisal Vol. 1, Bab 3, #1",
      linkedQuranVerses = "5:8, 42:37"
    ),
    HadithEntity(
      collectionKey = "khisal",
      collectionName = "Al-Khisal (Shaykh al-Saduq)",
      bookNumber = 1,
      bookName = "Book 1: Bab al-Arba'ah (باب الأربعة — Fourfold Qualities)",
      chapterNumber = 2,
      chapterName = "Four Pillars That Sustain Religion and Worldly Order",
      hadithNumber = 2,
      darussalamReference = "Al-Khisal Canonical: Vol. 1, Bab 4, #2",
      inBookReference = "In-Book: Part 4 (Fourfold Qualities), Hadith 2 • Thaqalayn API Ref",
      arabicNumber = 2,
      arabicText = "قِوَامُ الدُّنْيَا بِأَرْبَعَةٍ: بِعَالِمٍ يَسْتَعْمِلُ عِلْمَهُ، وَبِجَاهِلٍ لَا يَسْتَنْكِفُ أَنْ يَتَعَلَّمَ، وَبِغَنِيٍّ لَا يَبْخَلُ بِمَالِهِ، وَبِفَقِيرٍ لَا يَبِيعُ آخِرَتَهُ بِدُنْيَاهُ",
      transliteration = "Qiwamud-dunya bi-arba'ah: bi-'alimin yasta'milu 'ilmahu, wa bi-jahilin la yastankifu an yata'allama, wa bi-ghaniyyin la yabkhalu bi-malihi, wa bi-faqirin la yabi'u akhiratahu bi-dunyah.",
      englishText = "Amir al-Mu'minin 'Ali (AS) said: 'The order of the world is sustained by four pillars: a scholar who acts upon his knowledge, an unlearned person who is not too proud to learn, a wealthy person who is not stingy with his wealth, and a poor person who does not sell his Hereafter for his worldly gain.'",
      urduText = "امیر المومنین حضرت علی علیہ السلام نے فرمایا: دنیا کا نظام چار ستونوں پر قائم ہے: وہ عالم جو اپنے علم پر عمل کرے، وہ نادان جو سیکھنے سے عار نہ کرے، وہ مالدار جو اپنے مال میں بخل نہ کرے، اور وہ غریب جو اپنی دنیا کے بدلے اپنی آخرت نہ بیچے۔",
      narrator = "Amir al-Mu'minin 'Ali ibn Abi Talib (AS)",
      grade = "Mu'tabar (Al-Khisal)",
      gradingScholar = "Shaykh al-Saduq Ibn Babawayh",
      reference = "Al-Khisal Vol. 1, Bab 4, #2",
      linkedQuranVerses = "2:44, 92:5"
    ),

    // ==================== 'UYUN AKHBAR AL-RIDA (SHAYKH AL-SADUQ) ====================
    HadithEntity(
      collectionKey = "uyun_akhbar_rida",
      collectionName = "'Uyun Akhbar al-Rida (Shaykh al-Saduq)",
      bookNumber = 1,
      bookName = "Volume 1: Chapters on Divine Unity and Prophetic Ethics (أبواب التوحيد والأخلاق)",
      chapterNumber = 28,
      chapterName = "Completion of Intellect and Noble Treatment of People",
      hadithNumber = 1,
      darussalamReference = "'Uyun Canonical: Vol. 1, Ch. 28, #1",
      inBookReference = "In-Book: Vol. 1, Chapter 28, Hadith 1 • Thaqalayn API Ref",
      arabicNumber = 1,
      arabicText = "لَا يَكُونُ الْمُؤْمِنُ مُؤْمِنًا حَتَّى تَكُونَ فِيهِ ثَلَاثُ خِصَالٍ: سُنَّةٌ مِنْ رَبِّهِ، وَسُنَّةٌ مِنْ نَبِيِّهِ، وَسُنَّةٌ مِنْ وَلِيِّهِ؛ فَأَمَّا السُّنَّةُ مِنْ رَبِّهِ فَكِتْمَانُ سِرِّهِ، وَأَمَّا السُّنَّةُ مِنْ نَبِيِّهِ فَمُدَارَاةُ النَّاسِ، وَأَمَّا السُّنَّةُ مِنْ وَلِيِّهِ فَالصَّبْرُ فِي الْبَأْسَاءِ وَالضَّرَّاءِ",
      transliteration = "La yakunul-mu'minu mu'minan hatta takuna fihi thalathu khisalin: sunnatun min Rabbihi, wa sunnatun min Nabiyyihi, wa sunnatun min Waliyyihi...",
      englishText = "Imam 'Ali ibn Musa al-Rida (AS) said: 'A believer is not a true believer until he possesses three qualities: a way from his Lord, a way from his Prophet (ﷺ), and a way from his Wali (divinely guided leader). The way from his Lord is guarding secrets; the way from his Prophet is gentle kindness toward people; and the way from his Wali is patience in adversity and hardship.'",
      urduText = "امام علی بن موسیٰ الرضا علیہ السلام نے فرمایا: مومن اس وقت تک کامل مومن نہیں ہوتا جب تک اس میں تین سنتیں نہ ہوں: ایک سنت اس کے رب کی، ایک سنت اس کے نبی ﷺ کی، اور ایک سنت اس کے ولی کی۔ رب کی سنت راز کی حفاظت کرنا ہے، نبی ﷺ کی سنت لوگوں کے ساتھ نرمی اور خوش اخلاقی ہے، اور ولی کی سنت تنگدستی اور تکلیف میں صبر کرنا ہے۔",
      narrator = "Imam 'Ali ibn Musa al-Rida (AS)",
      grade = "Sahih (Imami Rijal Grading)",
      gradingScholar = "Shaykh al-Saduq & 'Allamah al-Majlisi",
      reference = "'Uyun Akhbar al-Rida Vol. 1, Ch. 28, #1",
      linkedQuranVerses = "2:177, 3:159"
    ),
    HadithEntity(
      collectionKey = "uyun_akhbar_rida",
      collectionName = "'Uyun Akhbar al-Rida (Shaykh al-Saduq)",
      bookNumber = 2,
      bookName = "Volume 2: Chapters on the Merits of Knowledge and Reason (أبواب فضل العلم والعقل)",
      chapterNumber = 30,
      chapterName = "The Friend of Every Person Is His Intellect",
      hadithNumber = 2,
      darussalamReference = "'Uyun Canonical: Vol. 2, Ch. 30, #2",
      inBookReference = "In-Book: Vol. 2, Chapter 30, Hadith 2 • Thaqalayn API Ref",
      arabicNumber = 2,
      arabicText = "صَدِيقُ كُلِّ امْرِئٍ عَقْلُهُ، وَعَدُوُّهُ جَهْلُهُ",
      transliteration = "Sadiqu kulli imri'in 'aqluhu, wa 'aduwwuhu jahluh.",
      englishText = "Imam 'Ali ibn Musa al-Rida (AS) said: 'The true friend of every person is his intellect, and his enemy is his ignorance.'",
      urduText = "امام علی بن موسیٰ الرضا علیہ السلام نے فرمایا: ہر شخص کا سچا دوست اس کی عقل ہے، اور اس کا دشمن اس کی جہالت ہے۔",
      narrator = "Imam 'Ali ibn Musa al-Rida (AS)",
      grade = "Sahih (Also in Al-Kafi Vol. 1, p. 11)",
      gradingScholar = "Shaykh al-Saduq & Shaykh al-Kulayni",
      reference = "'Uyun Akhbar al-Rida Vol. 2, Ch. 30, #2",
      linkedQuranVerses = "39:9, 67:10"
    ),

