      inBookReference = "In-Book: Assembly 1, Hadith 1 • Qom & Thaqalayn API Edition",
      arabicNumber = 1,
      arabicText = "مَنْ سَلَكَ طَرِيقًا يَطْلُبُ فِيهِ عِلْمًا سَلَكَ اللَّهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ، وَإِنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا لِطَالِبِ الْعِلْمِ رِضًا بِهِ",
      transliteration = "Man salaka tariqan yatlubu fihi 'ilman salakallahu bihi tariqan ilal-Jannah, wa innal-mala'ikata la-tada'u ajnihataha li-talibil-'ilmi ridan bih.",
      englishText = "Whoever travels a path in search of sacred knowledge, Allah leads him along a path to Paradise; and indeed the angels lower their wings for the seeker of knowledge out of pleasure with him.",
