      inBookReference = "In-Book: Assembly 27, Hadith 2 • Thaqalayn API Edition",
      arabicNumber = 2,
      arabicText = "رَحِمَ اللَّهُ عَبْدًا أَحْيَا أَمْرَنَا، قِيلَ: وَكَيْفَ يُحْيِي أَمْرَكُمْ؟ قَالَ: يَتَعَلَّمُ عُلُومَنَا وَيُعَلِّمُهَا النَّاسَ، فَإِنَّ النَّاسَ لَوْ عَلِمُوا مَحَاسِنَ كَلَامِنَا لَاتَّبَعُونَا",
      transliteration = "Rahimallahu 'abdan ahya amrana. Qila: Wa kayfa yuhyi amrakum? Qala: Yata'allamu 'ulumana wa yu'allimuhan-nas; fa-innan-nasa law 'alimu mahasina kalamina lattaba'una.",
      englishText = "Imam 'Ali ibn Musa al-Rida (AS) said: 'May Allah have mercy upon a servant who revives our cause.' He was asked: 'How is your cause revived?' He replied: 'He learns our sciences and teaches them to people; for indeed if people knew the beauty and wisdom of our words, they would follow us.'",
      urduText = "امام علی بن موسیٰ الرضا علیہ السلام نے فرمایا: اللہ اس بندے پر رحم فرمائے جو ہمارے امر کو زندہ کرے۔ پوچھا گیا: آپ کا امر کیسے زندہ کیا جاتا ہے؟ فرمایا: وہ ہمارے علوم کو سیکھے اور لوگوں کو سکھائے، کیونکہ اگر لوگ ہمارے کلام کے محاسن اور حکمت کو جان لیں تو ہماری پیروی کریں۔",
      narrator = "Imam 'Ali ibn Musa al-Rida (AS) via 'Abd al-Salam ibn Salih al-Harawi",
      grade = "Sahih (Al-Amali & Ma'ani al-Akhbar)",
      gradingScholar = "Shaykh al-Saduq Ibn Babawayh",
      reference = "Al-Amali (Al-Saduq) Majlis 27, #2",
      linkedQuranVerses = "16:125, 39:18"
