      urduText = "امام جعفر صادق علیہ السلام نے بسم اللہ الرحمن الرحیم کی تفسیر میں فرمایا: یہ ہر سورت کی ایک مستقل آیت ہے (سوائے سورۃ التوبہ کے)؛ الرحمٰن تمام مخلوقات پر رحم فرمانے والا ہے اور الرحیم مومنین پر خصوصی رحمت فرمانے والا ہے۔",
