      arabicNumber = 315,
      arabicText = "جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ فَقَالَ: يَا رَسُولَ اللَّهِ مَنْ أَبَرُّ؟ قَالَ: أُمَّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: أُمَّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: أُمَّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: أَبَاكَ",
      transliteration = "Ja'a rajulun ilan-Nabiyyi (ﷺ) faqala: Ya Rasulallah, man abarr? Qala: Ummak. Qala: Thumma man? Qala: Ummak. Qala: Thumma man? Qala: Ummak. Qala: Thumma man? Qala: Abak.",
      englishText = "A man came to the Prophet (ﷺ) and asked: 'O Messenger of Allah, to whom should I show the greatest kindness and devotion?' He replied: 'Your mother.' He asked: 'Then whom?' He said: 'Your mother.' He asked: 'Then whom?' He said: 'Your mother.' He asked: 'Then whom?' He said: 'Your father.'",
      urduText = "ایک شخص نبی اکرم ﷺ کی خدمت میں حاضر ہوا اور عرض کیا: یا رسول اللہ! میں سب سے زیادہ کس کے ساتھ حسنِ سلوک کروں؟ آپ ﷺ نے فرمایا: اپنی ماں کے ساتھ۔ اس نے پوچھا: پھر کس کے ساتھ؟ فرمایا: اپنی ماں کے ساتھ۔ اس نے پوچھا: پھر کس کے ساتھ؟ فرمایا: اپنی ماں کے ساتھ۔ اس نے پوچھا: پھر کس کے ساتھ؟ فرمایا: اپنے باپ کے ساتھ۔",
