    HadithEntity(
      collectionKey = "tirmidhi",
      collectionName = "Jami` at-Tirmidhi",
      bookNumber = 27,
      bookName = "Book 27: Kitab al-Birr was-Silah (كتاب البر والصلة)",
      chapterNumber = 62,
