    // ==================== HISTORY OF ISLAM — SUNNI CLASSICAL CHRONICLES ====================
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 1,
      bookName = "Book 1: Al-Sirah al-Nabawiyyah — Hijrah & Constitution of Madinah (1 AH)",
      chapterNumber = 1,
      chapterName = "The Hijrah to Madinah, Brotherhood (Mu'akhah), and Sahifat al-Madinah",
      hadithNumber = 1,
      darussalamReference = "Sirah Ibn Hisham: Vol. 1, p. 501 (#1)",
      inBookReference = "In-Book: Book 1, Hadith 1 • Al-Bidaya wa'l-Nihaya Vol. 3, p. 224 (1 AH)",
      arabicNumber = 1,
      arabicText = "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، هَذَا كِتَابٌ مِنْ مُحَمَّدٍ النَّبِيِّ بَيْنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ مِنْ قُرَيْشٍ وَيَثْرِبَ وَمَنْ تَبِعَهُمْ فَلَحِقَ بِهِمْ وَجَاهَدَ مَعَهُمْ، أَنَّهُمْ أُمَّةٌ وَاحِدَةٌ مِنْ دُونِ النَّاسِ",
      transliteration = "Bismillahir-Rahmanir-Rahim. Hadha kitabun min Muhammadin an-Nabiyyi baynal-mu'minina wal-muslimina min Qurayshin wa Yathriba wa man tabi'ahum fa-lahiqa bihim wa jahada ma'ahum, annahum ummatun wahidatun min dunin-nas.",
      englishText = "In the Name of Allah, the Most Merciful, the Especially Merciful. This is a constitutional document from Muhammad the Prophet (ﷺ) governing relations between the believers and Muslims of Quraysh and Yathrib (Madinah), and those who followed and joined them and strove alongside them: they constitute a single community (Ummah Wahidah) distinct from other people. [Documented in Sirah Ibn Hisham & Ibn Kathir's Al-Bidaya wa'l-Nihaya, 1 AH].",
      urduText = "بسم اللہ الرحمن الرحیم۔ یہ محمد نبی ﷺ کی جانب سے قریش اور یثرب (مدینہ) کے مومنوں اور مسلمانوں اور ان کے ساتھ شامل ہو کر جہاد کرنے والوں کے درمیان دستوری تحریر (میثاقِ مدینہ) ہے کہ وہ سب دوسرے لوگوں کے مقابلے میں ایک ہی امت (امۃ واحدۃ) ہیں۔ (سیرت ابن ہشام جلد 1 ص 501، البدایہ والنہایہ جلد 3 ص 224)۔",
      narrator = "Ibn Ishaq / Ibn Hisham & Imam Ahmad ibn Hanbal",
      grade = "Authentic Historical Document (Sahih fil-Sirah)",
      gradingScholar = "Ibn Hisham (Sirah), Hafiz Ibn Kathir (Al-Bidaya wa'l-Nihaya) & Dr. Akram Diya' al-'Umari",
      reference = "Sirah Ibn Hisham 1:501 • Al-Bidaya wa'l-Nihaya 3:224",
      linkedQuranVerses = "8:72, 9:40, 3:103"
    ),
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 2,
      bookName = "Book 2: Ghazwat Badr al-Kubra — The Great Battle of Badr (17 Ramadan 2 AH)",
      chapterNumber = 1,
      chapterName = "The Prophet's Supplication at Badr and the Decisive Victory (Yawm al-Furqan)",
      hadithNumber = 2,
      darussalamReference = "Tarikh al-Tabari: Vol. 2, p. 449 (#2)",
      inBookReference = "In-Book: Book 2, Hadith 2 • Sahih al-Bukhari 3953 • Sahih Muslim 1763",
      arabicNumber = 2,
      arabicText = "اللَّهُمَّ أَنْجِزْ لِي مَا وَعَدْتَنِي، اللَّهُمَّ آتِ مَا وَعَدْتَنِي، اللَّهُمَّ إِنْ تُهْلِكْ هَذِهِ الْعِصَابَةَ مِنْ أَهْلِ الإِسْلاَمِ لاَ تُعْبَدْ فِي الأَرْضِ",
      transliteration = "Allahumma anjiz li ma wa'adtani, Allahumma ati ma wa'adtani, Allahumma in tuhlik hadhihil-'isabata min ahlil-Islami la tu'bad fil-ard.",
      englishText = "At the Battle of Badr (17 Ramadan 2 AH / 624 CE), the Prophet (ﷺ) faced the Qiblah with the 313 companions and supplicated earnestly: 'O Allah, fulfill for me what You promised me! O Allah, if this small band of Muslims perishes today, You will not be worshipped on earth.' Thereafter Allah revealed Surah al-Anfal (8:9): 'Indeed, I will reinforce you with a thousand angels following one another.' [Recorded in Sahih Muslim 1763, Sahih al-Bukhari 3953, and Tarikh al-Tabari Vol. 2].",
      urduText = "غزوہ بدر الکبریٰ (17 رمضان 2 ہجری) کے دن نبی اکرم ﷺ نے 313 صحابہ کرام کے ہمراہ قبلہ رخ ہو کر التجا فرمائی: اے اللہ! مجھ سے کیا ہوا وعدہ پورا فرما، اے اللہ! اگر اہلِ اسلام کی یہ چھوٹی سی جماعت آج ہلاک ہو گئی تو زمین پر تیری عبادت نہیں کی جائے گی۔ اس پر اللہ تعالیٰ نے سورۃ الانفال آیت 9 نازل فرمائی۔ (صحیح مسلم 1763، تاریخ طبری جلد 2 ص 449)۔",
      narrator = "'Umar ibn al-Khattab & Ibn 'Abbas (RA)",
      grade = "Sahih Muttafaqun 'Alayh & Canonical Historical Account",
      gradingScholar = "Imam Muslim, Imam al-Bukhari, Imam al-Tabari & Hafiz Ibn Kathir",
      reference = "Sahih Muslim 1763 • Tarikh al-Tabari 2:449",
      linkedQuranVerses = "8:9, 3:123"
    ),
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 3,
      bookName = "Book 3: Ghazwat Uhud — Battle of Uhud & Archers' Mount (Shawwal 3 AH)",
      chapterNumber = 1,
      chapterName = "Steadfastness of the Prophet (ﷺ) and the Lesson of Jabal al-Rumat at Uhud",
      hadithNumber = 3,
      darussalamReference = "Sahih al-Bukhari: #3039 / Tarikh al-Tabari Vol. 2 (#3)",
      inBookReference = "In-Book: Book 3, Hadith 3 • Al-Bidaya wa'l-Nihaya Vol. 4, p. 14",
      arabicNumber = 3,
      arabicText = "اقْصُدُوا يَا مَعْشَرَ الرُّمَاةِ، إِنْ رَأَيْتُمُونَا تَخْطَفُنَا الطَّيْرُ فَلَا تَبْرَحُوا مَكَانَكُمْ هَذَا حَتَّى أُرْسِلَ إِلَيْكُمْ",
      transliteration = "Uqsudu ya ma'sharar-rumati, in ra'aytumuna takhtafunat-tayru fala tabrahu makanakum hadha hatta ursila ilaykum.",
      englishText = "On the Day of Uhud (Shawwal 3 AH / 625 CE), the Prophet (ﷺ) appointed 'Abdullah ibn Jubayr (RA) over fifty archers on Jabal al-Rumat and instructed them: 'Even if you see birds snatching us away, do not leave this position of yours until I send word to you.' When the majority left their post thinking the battle was over, Khalid ibn al-Walid's cavalry flanked the Muslims, testing the believers and martyring seventy companions including Hamzah ibn 'Abd al-Muttalib (RA). [Sahih al-Bukhari 3039, Al-Bidaya wa'l-Nihaya Vol. 4].",
      urduText = "غزوہ احد (شوال 3 ہجری) کے موقع پر نبی کریم ﷺ نے حضرت عبداللہ بن جبیر رضی اللہ عنہ کو پچاس تیر اندازوں کا امیر مقرر کر کے جبلِ رماۃ پر تعینات فرمایا اور حکم دیا: اگر تم دیکھو کہ پرندے ہمیں اچک رہے ہیں تب بھی اپنی جگہ ہرگز نہ چھوڑنا جب تک میں تمہیں پیغام نہ بھیجوں۔ اس تاریخی واقعے اور سید الشہداء حضرت حمزہ رضی اللہ عنہ کی شہادت کا تفصیلی بیان صحیح بخاری 3039 اور البدایہ والنہایہ جلد 4 میں محفوظ ہے۔",
      narrator = "Al-Bara' ibn 'Azib (RA)",
      grade = "Sahih (Sahih al-Bukhari & Classical Maghazi)",
      gradingScholar = "Imam al-Bukhari (3039) & Hafiz Ibn Kathir",
      reference = "Sahih al-Bukhari 3039 • Al-Bidaya wa'l-Nihaya 4:14",
      linkedQuranVerses = "3:152, 3:165, 3:169"
    ),
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 4,
      bookName = "Book 4: Battle of the Trench (Khandaq, 5 AH) & Treaty of Hudaybiyyah (6 AH)",
      chapterNumber = 1,
      chapterName = "Digging the Trench at Madinah and the Pledge of Ridwan (Bay'at al-Ridwan)",
      hadithNumber = 4,
      darussalamReference = "Sahih al-Bukhari: #4104 / Sirah Ibn Hisham Vol. 2 (#4)",
      inBookReference = "In-Book: Book 4, Hadith 4 • Al-Bidaya wa'l-Nihaya Vol. 4, p. 94",
      arabicNumber = 4,
      arabicText = "اللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ الْآخِرَهْ، فَاغْفِرْ لِلْأَنْصَارِ وَالْمُهَاجِرَهْ",
      transliteration = "Allahumma la 'aysha illa 'ayshul-akhirah, faghfir lil-Ansari wal-Muhajirah.",
      englishText = "During the Siege of the Trench (Ghazwat al-Khandaq / Al-Ahzab, 5 AH) advised by Salman al-Farisi (RA), the Prophet (ﷺ) carried earth with the companions reciting: 'O Allah, there is no true life except the life of the Hereafter, so forgive the Ansar and the Muhajirun.' The following year (6 AH), the Treaty of Hudaybiyyah and Bay'at al-Ridwan laid the peaceful foundation for the spread of Islam across Arabia, called in Surah al-Fath (48:1) a 'Clear Victory'.",
      urduText = "غزوہ خندق (احزاب، 5 ہجری) میں حضرت سلمان فارسی رضی اللہ عنہ کے مشورے سے خندق کھودی گئی اور نبی کریم ﷺ خود صحابہ کے ساتھ مٹی اٹھاتے ہوئے فرماتے تھے: اے اللہ! اصل زندگی تو آخرت ہی کی زندگی ہے، پس انصار اور مہاجرین کی مغفرت فرما۔ اس کے بعد 6 ہجری میں صلح حدیبیہ اور بیعتِ رضوان واقع ہوئی جسے قرآن مجید نے فتحِ مبین قرار دیا۔ (صحیح بخاری 4104، البدایہ والنہایہ جلد 4)۔",
      narrator = "Anas ibn Malik & Sahl ibn Sa'd (RA)",
      grade = "Sahih (Muttafaqun 'Alayh)",
      gradingScholar = "Imam al-Bukhari, Imam Muslim & Hafiz Ibn Kathir",
      reference = "Sahih al-Bukhari 4104 • Al-Bidaya wa'l-Nihaya 4:94",
      linkedQuranVerses = "33:9, 48:1, 48:18"
    ),
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 5,
      bookName = "Book 5: Battle of Khaybar (7 AH) & Conquest of Makkah (Fath Makkah, 8 AH)",
      chapterNumber = 1,
      chapterName = "The Banner at Khaybar and the General Amnesty at the Conquest of Makkah",
      hadithNumber = 5,
      darussalamReference = "Sahih al-Bukhari: #4210 / Tarikh al-Tabari Vol. 3 (#5)",
      inBookReference = "In-Book: Book 5, Hadith 5 • Sahih Muslim 2406 • Sirah Ibn Hisham Vol. 2",
      arabicNumber = 5,
      arabicText = "لَأُعْطِيَنَّ الرَّايَةَ غَدًا رَجُلًا يُفْتَحُ عَلَى يَدَيْهِ يُحِبُّ اللَّهَ وَرَسُولَهُ وَيُحِبُّهُ اللَّهُ وَرَسُولُهُ",
      transliteration = "La-u'tiyannar-rayata ghadan rajulan yuftahu 'ala yadayhi yuhibbullaha wa Rasuluh wa yuhibbuhullahu wa Rasuluh.",
      englishText = "At the Battle of Khaybar (7 AH), the Prophet (ﷺ) declared: 'Tomorrow I shall certainly give the banner to a man at whose hands victory will be granted, who loves Allah and His Messenger and whom Allah and His Messenger love,' and he gave it to 'Ali ibn Abi Talib (RA). In Ramadan 8 AH (630 CE), at the Conquest of Makkah (Fath Makkah), the Prophet (ﷺ) entered in humility and granted general amnesty: 'Go, for you are free (Idhhabu fa-antum al-tulaqa').'",
      urduText = "غزوہ خیبر (7 ہجری) کے موقع پر رسول اللہ ﷺ نے فرمایا: کل میں یہ علم ایک ایسے شخص کو دوں گا جس کے ہاتھوں پر اللہ فتح عطا فرمائے گا، جو اللہ اور اس کے رسول سے محبت کرتا ہے اور اللہ اور اس کے رسول اس سے محبت کرتے ہیں؛ چنانچہ آپ ﷺ نے علم حضرت علی بن ابی طالب رضی اللہ عنہ کو عطا فرمایا۔ پھر رمضان 8 ہجری میں فتح مکہ کے موقع پر عام معافی کا اعلان فرمایا۔ (صحیح بخاری 4210، صحیح مسلم 2406)۔",
      narrator = "Sahl ibn Sa'd al-Sa'idi (RA)",
      grade = "Sahih (Muttafaqun 'Alayh)",
      gradingScholar = "Imam al-Bukhari, Imam Muslim & Hafiz Ibn Hajar (Fath al-Bari)",
      reference = "Sahih al-Bukhari 4210 • Sahih Muslim 2406",
      linkedQuranVerses = "48:27, 110:1, 110:2"
    ),
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 6,
      bookName = "Book 6: Battle of Yarmouk (Ma'rakat al-Yarmuk — معركة اليرموك, 15 AH / 636 CE)",
      chapterNumber = 1,
      chapterName = "The Decisive Battle of Yarmouk in Bilad al-Sham under Abu 'Ubaydah & Khalid ibn al-Walid",
      hadithNumber = 6,
      darussalamReference = "Tarikh al-Tabari: Vol. 3, p. 395 / Al-Bidaya wa'l-Nihaya Vol. 7 (#6)",
      inBookReference = "In-Book: Book 6, Hadith 6 • Futuh al-Buldan (Al-Baladhuri) p. 141 • Siyar A'lam al-Nubala' Vol. 1",
      arabicNumber = 6,
      arabicText = "إِنَّ هَذَا يَوْمٌ مِنْ أَيَّامِ اللَّهِ، لَا يَنْبَغِي فِيهِ الْفَخْرُ وَلَا الْبَغْيُ، أَخْلِصُوا جِهَادَكُمْ وَأَرِيدُوا اللَّهَ بِعَمَلِكُمْ",
      transliteration = "Inna hadha yawmun min ayyamillahi, la yanbaghi fihil-fakhru wa lal-baghy, akhlisu jihadakum wa aridullaha bi-'amalikum.",
      englishText = "At the Battle of Yarmouk (Ma'rakat al-Yarmuk, Rajab 15 AH / August 636 CE), Khalid ibn al-Walid, Abu 'Ubaydah ibn al-Jarrah, 'Amr ibn al-'As, Yazid ibn Abi Sufyan, and 'Ikrimah ibn Abi Jahl (RA) united the Muslim corps facing the Byzantine imperial army along the Yarmouk River. Khalid exhorted the ranks: 'This is one of the Days of Allah; neither pride nor transgression befits it. Make your striving sincere and seek Allah alone by your deeds.' The six-day engagement decisively opened Bilad al-Sham and Jerusalem. [Documented in Tarikh al-Tabari Vol. 3, pp. 395–409; Ibn Kathir, Al-Bidaya wa'l-Nihaya Vol. 7, pp. 8–19; Al-Baladhuri, Futuh al-Buldan].",
      urduText = "معرکہ یرموک (جنگِ یرموک، رجب 15 ہجری / اگست 636ء) بلادِ شام میں دریائے یرموک کے کنارے مسلمانوں اور بازنطینی سلطنت کی افواج کے درمیان پیش آیا۔ حضرت ابو عبیدہ بن الجراح، حضرت خالد بن ولید، حضرت عمرو بن العاص اور حضرت عکرمہ بن ابی جہل رضی اللہ عنہم نے اسلامی لشکر کی قیادت کی۔ حضرت خالد بن ولیدؓ نے فرمایا: یہ اللہ کے ایام میں سے ایک دن ہے، اس میں فخر اور زیادتی زیبا نہیں، اپنے عمل کو خالص اللہ کے لیے رکھو۔ چھ روزہ تاریخی معرکے کے نتیجے میں شام اور بیت المقدس کی فتح کا راستہ ہموار ہوا۔ (تاریخ طبری جلد 3 ص 395، البدایہ والنہایہ لابن کثیر جلد 7 ص 8، فتوح البلدان للبلادھری)۔",
      narrator = "Imam Ibn Jarir al-Tabari, Al-Baladhuri & Hafiz Ibn Kathir",
      grade = "Mutawatir Historical Event (Authenticated Sunni Chronicles)",
      gradingScholar = "Hafiz Ibn Kathir (Al-Bidaya wa'l-Nihaya Vol. 7) & Imam al-Dhahabi (Tarikh al-Islam)",
      reference = "Tarikh al-Tabari 3:395 • Al-Bidaya wa'l-Nihaya 7:8",
      linkedQuranVerses = "30:2, 30:3, 30:4, 8:46"
    ),
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 7,
      bookName = "Book 7: Battle of al-Qadisiyyah (Ma'rakat al-Qadisiyyah — معركة القادسية, 14–15 AH / 636 CE)",
      chapterNumber = 1,
      chapterName = "Sa'd ibn Abi Waqqas, Rib'i ibn 'Amir's Embassy, and the Four Days of al-Qadisiyyah",
      hadithNumber = 7,
      darussalamReference = "Tarikh al-Tabari: Vol. 3, p. 520 / Al-Bidaya wa'l-Nihaya Vol. 7 (#7)",
      inBookReference = "In-Book: Book 7, Hadith 7 • Al-Kamil fi al-Tarikh (Ibn al-Athir) Vol. 2, p. 452",
      arabicNumber = 7,
      arabicText = "إِنَّ اللَّهَ ابْتَعَثَنَا لِنُخْرِجَ مَنْ شَاءَ مِنْ عِبَادَةِ الْعِبَادِ إِلَى عِبَادَةِ اللَّهِ، وَمِنْ ضِيقِ الدُّنْيَا إِلَى سَعَتِهَا، وَمِنْ جَوْرِ الْأَدْيَانِ إِلَى عَدْلِ الْإِسْلَامِ",
      transliteration = "Innallaha ibta'athana li-nukhrija man sha'a min 'ibadatil-'ibadi ila 'ibadatillahi, wa min diqid-dunya ila sa'atiha, wa min jawril-adyani ila 'adlil-Islam.",
      englishText = "Before the Battle of al-Qadisiyyah (14–15 AH / 636 CE) during the Caliphate of 'Umar ibn al-Khattab (RA), the commander Sa'd ibn Abi Waqqas (RA) sent Rib'i ibn 'Amir (RA) to the Sasanian commander Rustam. Rib'i declared the famous historical statement: 'Allah has sent us to bring forth whomever He wills from the servitude of human beings to the worship of Allah alone, from the narrowness of this world to its vastness, and from the tyranny of religions to the justice of Islam.' The four-day Battle of al-Qadisiyyah (Yawm Armath, Yawm Aghwath, Yawm 'Imas, and Laylat al-Harir) with reinforcements led by al-Qa'qa' ibn 'Amr and Hashim ibn 'Utbah resulted in the decisive opening of Iraq and Ctesiphon (al-Mada'in). [Tarikh al-Tabari Vol. 3, p. 520; Ibn Kathir, Al-Bidaya wa'l-Nihaya Vol. 7, p. 38].",
      urduText = "معرکہ قادسیہ (جنگِ قادسیہ، 14–15 ہجری / 636ء) خلیفہ دوم حضرت عمر بن خطاب رضی اللہ عنہ کے عہد میں حضرت سعد بن ابی وقاص رضی اللہ عنہ کی سپہ سالاری میں لڑا گیا۔ جنگ سے قبل حضرت ربعی بن عامر رضی اللہ عنہ نے ایرانی سپہ سالار رستم کے دربار میں تاریخی کلمات کہے: اللہ نے ہمیں اس لیے بھیجا ہے تاکہ ہم بندوں کو بندوں کی غلامی سے نکال کر اللہ وحدہٗ کی عبادت کی طرف لائیں، دنیا کی تنگی سے اس کی وسعت کی طرف، اور ادیان کے ظلم سے اسلام کے عدل کی طرف لائیں۔ چار روزہ معرکہ قادسیہ (یوم ارماث، یوم اغواث، یوم عماس اور لیلۃ الہریر) کے نتیجے میں عراق اور مدائن فتح ہوئے۔ (تاریخ طبری جلد 3 ص 520، البدایہ والنہایہ جلد 7 ص 38، الکامل فی التاریخ جلد 2 ص 452)۔",
      narrator = "Imam Ibn Jarir al-Tabari, Ibn al-Athir & Hafiz Ibn Kathir",
      grade = "Famous & Authenticated Historical Account (Mashhur fil-Tarikh)",
      gradingScholar = "Imam al-Tabari, Ibn al-Athir & Hafiz Ibn Kathir",
      reference = "Tarikh al-Tabari 3:520 • Al-Bidaya wa'l-Nihaya 7:38",
      linkedQuranVerses = "21:105, 24:55, 3:110"
    ),
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 8,
      bookName = "Book 8: Conquest of Jerusalem (Fath Bayt al-Maqdis, 16 AH) & Covenant of 'Umar",
      chapterNumber = 1,
      chapterName = "Caliph 'Umar ibn al-Khattab's Entry into Jerusalem and Assurance of Safety ('Uhdat 'Umar)",
      hadithNumber = 8,
      darussalamReference = "Tarikh al-Tabari: Vol. 3, p. 609 / Futuh al-Buldan (#8)",
      inBookReference = "In-Book: Book 8, Hadith 8 • Al-Bidaya wa'l-Nihaya Vol. 7, p. 55 (15–16 AH)",
      arabicNumber = 8,
      arabicText = "هَذَا مَا أَعْطَى عَبْدُ اللَّهِ عُمَرُ أَمِيرُ الْمُؤْمِنِينَ أَهْلَ إِيلِيَاءَ مِنَ الْأَمَانِ: أَعْطَاهُمْ أَمَانًا لِأَنْفُسِهِمْ وَأَمْوَالِهِمْ وَلِكَنَائِسِهِمْ وَصُلْبَانِهِمْ",
      transliteration = "Hadha ma a'ta 'Abdullahi 'Umaru Amirul-Mu'minina ahla Iliya'a minal-aman: a'tahum amanan li-anfusihim wa amwalihim wa li-kana'isihim wa sulbanihim.",
      englishText = "Upon the peaceful handover of Jerusalem (Iliya' / Bayt al-Maqdis, 15–16 AH / 637 CE), Caliph 'Umar ibn al-Khattab (RA) travelled in person and issued the Covenant of 'Umar ('Uhdat 'Umar): 'This is the assurance of safety which the servant of Allah, 'Umar, Commander of the Faithful, grants to the people of Iliya' (Jerusalem): He grants them security for their lives, their property, their churches, and their crosses; their churches shall neither be occupied nor demolished, nor shall anyone be coerced in their religion.' [Documented in Tarikh al-Tabari Vol. 3, p. 609; Ibn Kathir, Al-Bidaya wa'l-Nihaya Vol. 7, p. 55].",
      urduText = "فتحِ بیت المقدس (15–16 ہجری / 637ء) کے موقع پر امیر المومنین حضرت عمر بن خطاب رضی اللہ عنہ خود شام تشریف لے گئے اور اہلِ ایلیاء (بیت المقدس) کو تاریخی عہد نامہ (عہدہ عمریہ) عطا فرمایا: یہ وہ امان ہے جو اللہ کے بندے عمر امیر المومنین نے اہلِ ایلیاء کو دی؛ ان کی جانوں، مالوں، گرجا گھروں اور صلیبوں کو امان دی جاتی ہے اور دین کے معاملے میں کسی پر جبر نہیں کیا جائے گا۔ (تاریخ طبری جلد 3 ص 609، البدایہ والنہایہ جلد 7 ص 55)۔",
      narrator = "Imam Ibn Jarir al-Tabari & Hafiz Ibn Kathir",
      grade = "Documented Classical Historical Covenant",
      gradingScholar = "Imam al-Tabari, Al-Baladhuri & Hafiz Ibn Kathir",
      reference = "Tarikh al-Tabari 3:609 • Al-Bidaya wa'l-Nihaya 7:55",
      linkedQuranVerses = "2:256, 60:8, 17:1"
    ),
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 9,
      bookName = "Book 9: Martyrdom of Imam al-Husayn ibn 'Ali (RA) at Karbala (10 Muharram 61 AH)",
      chapterNumber = 1,
      chapterName = "Sunni Classical Account of the Tragedy of Karbala and Condemnation of His Killers",
      hadithNumber = 9,
      darussalamReference = "Tarikh al-Tabari: Vol. 5, p. 400 / Al-Bidaya wa'l-Nihaya Vol. 8 (#9)",
      inBookReference = "In-Book: Book 9, Hadith 9 • Sahih al-Bukhari 3748 • Siyar A'lam al-Nubala' Vol. 3, p. 280",
      arabicNumber = 9,
      arabicText = "الْحَسَنُ وَالْحُسَيْنُ سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ",
      transliteration = "Al-Hasanu wal-Husaynu sayyida shababi ahlil-Jannah.",
      englishText = "The Prophet (ﷺ) said: 'Al-Hasan and al-Husayn are the masters of the youth of Paradise.' (Jami' at-Tirmidhi 3768, Sahih). In Muharram 61 AH (October 680 CE), the grandson of the Prophet (ﷺ), al-Husayn ibn 'Ali (RA), and the noble members of his household were martyred at Karbala by the Kufan army dispatched by 'Ubaydullah ibn Ziyad under 'Umar ibn Sa'd. Hafiz Ibn Kathir writes in Al-Bidaya wa'l-Nihaya (Vol. 8, p. 202): 'Every Muslim ought to grieve over his martyrdom, for he is among the foremost masters of the Muslims, the scholarly companions, and the son of the foremost daughter of the Messenger of Allah (ﷺ).' Imam al-Dhahabi writes in Siyar A'lam al-Nubala' (Vol. 3, p. 280) that al-Husayn died a pure martyr confronting injustice.",
      urduText = "نبی کریم ﷺ نے فرمایا: حسن اور حسین جنت کے نوجوانوں کے سردار ہیں (جامع ترمذی 3768، صحیح)۔ 10 محرم 61 ہجری (680ء) کو میدانِ کربلا میں نواسۂ رسول حضرت امام حسین بن علی رضی اللہ عنہما اور آپ کے اہلِ بیت و رفقاء کو عبیداللہ بن زیاد کے بھیجے گئے لشکر نے شہید کیا۔ حافظ ابن کثیر ’البدایہ والنہایہ‘ (جلد 8 ص 202) اور امام ذہبی ’سیر اعلام النبلاء‘ (جلد 3 ص 280) میں لکھتے ہیں کہ ہر مسلمان کو سیدنا حسینؓ کی شہادت پر غمزدہ ہونا چاہیے کیونکہ آپ مسلمانوں کے عظیم سردار اور رسول اللہ ﷺ کی سب سے افضل صاحبزادی کے فرزند تھے۔",
      narrator = "Abu Sa'id al-Khudri, Anas ibn Malik (RA), Imam al-Tabari, Imam al-Dhahabi & Hafiz Ibn Kathir",
      grade = "Sahih Hadith & Authenticated Historical Consensus",
      gradingScholar = "Imam at-Tirmidhi, Imam al-Dhahabi (Siyar A'lam al-Nubala') & Hafiz Ibn Kathir",
      reference = "Al-Bidaya wa'l-Nihaya 8:202 • Siyar A'lam al-Nubala' 3:280",
      linkedQuranVerses = "33:33, 42:23"
    ),
    HadithEntity(
      collectionKey = "sunni_history",
      collectionName = "History of Islam — Sunni Chronicles",
      bookNumber = 10,
      bookName = "Book 10: Waqia Harrah — The Battle of al-Harrah in Madinah (Waq'at al-Harrah — وقعة الحرة, 63 AH / 683 CE)",
      chapterNumber = 1,
      chapterName = "The Event of al-Harrah (Waqia Hurrah) in Madinah and Classical Sunni Scholarly Assessment",
      hadithNumber = 10,
      darussalamReference = "Tarikh al-Tabari: Vol. 5, p. 482 / Al-Bidaya wa'l-Nihaya Vol. 8, p. 217 (#10)",
      inBookReference = "In-Book: Book 10, Hadith 10 • Sahih Muslim 1362 • Siyar A'lam al-Nubala' Vol. 3, p. 322",
      arabicNumber = 10,
      arabicText = "مَنْ أَخَافَ أَهْلَ الْمَدِينَةِ ظُلْمًا أَخَافَهُ اللَّهُ، وَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ صَرْفًا وَلَا عَدْلًا",
      transliteration = "Man akhafa ahlal-Madinati zulman akhafahullahu, wa 'alayhi la'natullahi wal-mala'ikati wan-nasi ajma'in, la yaqbalullahu minhu yawmal-qiyamati sarfan wa la 'adla.",
      englishText = "Waqia Harrah / Battle of al-Harrah (Waq'at al-Harrah — وقعة الحرة, Dhu al-Hijjah 63 AH / August 683 CE): When the people of Madinah led by the Companion 'Abdullah ibn Hanzalah (Ghasil al-Mala'ikah) and 'Abdullah ibn Muti' repudiated allegiance to Yazid ibn Mu'awiyah over his misconduct and the tragedy of Karbala, Yazid dispatched an army under Muslim ibn 'Uqbah al-Murri. At Harrat Waqim east of Madinah, the people of Madinah were defeated, hundreds of Ansar, Muhajirun, and Qurra' (including 80 remaining Companions according to al-Zuhri and Ibn Kathir) were killed, and Madinah was violated for three days. Hafiz Ibn Kathir (Al-Bidaya wa'l-Nihaya Vol. 8, pp. 217–224) and Imam al-Dhahabi (Siyar A'lam al-Nubala' Vol. 3, p. 322) cite the authentic Hadith of the Prophet (ﷺ) in Sahih Muslim (1362): 'Whoever unjustly terrifies the people of Madinah, Allah will terrify him, and upon him is the curse of Allah, the angels, and all mankind,' and severely condemn Muslim ibn 'Uqbah's assault on the Sanctuary of the Prophet (ﷺ).",
      urduText = "واقعہ حرہ (معرکہ حرہ / وقعة الحرة، ذوالحجہ 63 ہجری / اگست 683ء): جب اہلِ مدینہ نے حضرت عبداللہ بن حنظلہ (غسیل الملائکہ) رضی اللہ عنہ کی قیادت میں یزید بن معاویہ کے فسق اور سانحۂ کربلا کے بعد اس کی بیعت سے انکار کیا تو یزید نے مسلم بن عقبہ مری کی سرکردگی میں لشکر بھیجا۔ مدینہ منورہ کے مشرقی لاوے کے میدان ’حرۃ واقم‘ میں جنگ ہوئی جس میں صحابہ کرام، انصار، مہاجرین اور تابعین کی بڑی جماعت شہید ہوئی اور تین دن تک مدینہ منورہ کی حرمت پامال کی گئی۔ حافظ ابن کثیر نے ’البدایہ والنہایہ‘ (جلد 8 ص 217 تا 224) اور امام ذہبی نے ’سیر اعلام النبلاء‘ (جلد 3 ص 322) اور ’تاریخ الاسلام‘ میں صحیح مسلم (1362) کی حدیث نقل کی ہے کہ رسول اللہ ﷺ نے فرمایا: ’جس نے اہلِ مدینہ کو ظلم کے ساتھ خوفزدہ کیا، اللہ اسے خوفزدہ کرے گا اور اس پر اللہ، فرشتوں اور تمام انسانوں کی لعنت ہے‘، اور ائمہ اہلسنت نے واقعہ حرہ کو تاریخِ اسلام کے عظیم ترین فجائع میں شمار کیا ہے۔",
      narrator = "as-Sa'ib ibn Khallad (RA) [Sahih Muslim], Imam al-Tabari, Imam al-Dhahabi & Hafiz Ibn Kathir",
      grade = "Sahih Hadith & Mutawatir Historical Account (Waq'at al-Harrah 63 AH)",
      gradingScholar = "Imam Muslim (1362), Imam Ahmad (16557), Imam al-Dhahabi & Hafiz Ibn Kathir",
      reference = "Al-Bidaya wa'l-Nihaya 8:217 • Tarikh al-Tabari 5:482 • Sahih Muslim 1362",
      linkedQuranVerses = "33:60, 22:25"
    ),

    // ==================== HISTORY OF ISLAM — SHIA CLASSICAL CHRONICLES ====================
    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 1,
      bookName = "Book 1: Al-Bi'thah, Yawm al-Dar, Laylat al-Mabit & Hijrah (13 BH – 1 AH)",
      chapterNumber = 1,
      chapterName = "Imam 'Ali's (AS) First Acceptance of Islam and Sleeping on the Prophet's Bed (Laylat al-Mabit)",
      hadithNumber = 1,
      darussalamReference = "Kitab al-Irshad (Shaykh al-Mufid): Vol. 1, p. 51 (#1)",
      inBookReference = "In-Book: Book 1, Hadith 1 • Tarikh al-Ya'qubi Vol. 2, p. 38 • A'lam al-Wara Vol. 1",
      arabicNumber = 1,
      arabicText = "وَمِنَ النَّاسِ مَنْ يَشْرِي نَفْسَهُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ وَاللَّهُ رَءُوفٌ بِالْعِبَادِ",
      transliteration = "Wa minan-nasi man yashri nafsahu ibtigha'a mardatillahi wallahu Ra'ufun bil-'ibad.",
      englishText = "In Kitab al-Irshad (Vol. 1, pp. 51–56) by Shaykh al-Mufid and Tarikh al-Ya'qubi (Vol. 2, p. 38), on the Night of the Hijrah (Laylat al-Mabit, 1 AH), when Quraysh plotted to assassinate the Prophet (ﷺ), Amir al-Mu'minin 'Ali ibn Abi Talib (AS) slept on the Prophet's bed wrapped in his green Hadrami cloak to ransom the Messenger of Allah (ﷺ) with his own life, and remained in Makkah for three days to return all entrusted deposits (Amanat) before migrating to Madinah. Exegetes and historians record that Surah al-Baqarah 2:207 was revealed in honor of this sacrifice.",
      urduText = "شیخ مفید کی ’کتاب الارشاد‘ (جلد 1 ص 51) اور ’تاریخ یعقوبی‘ (جلد 2 ص 38) میں مروی ہے کہ ہجرت کی رات (لیلۃ المبیت، 1 ہجری) جب قریش نے نبی اکرم ﷺ کے گھر کا محاصرہ کیا تو امیر المومنین حضرت علی ابن ابی طالب علیہ السلام نے اپنی جان کا نذرانہ پیش کرتے ہوئے رسول اللہ ﷺ کے بستر پر آرام فرمایا اور تین دن مکہ میں رہ کر لوگوں کی امانتیں واپس لوٹانے کے بعد مدینہ ہجرت فرمائی۔ مفسرین و مورخین کے نزدیک سورۃ البقرہ آیت 207 اسی موقع پر نازل ہوئی۔",
      narrator = "Shaykh al-Mufid (Kitab al-Irshad), Ahmad al-Ya'qubi & Shaykh al-Tabarsi",
      grade = "Mutawatir Historical Account in Imami Chronicles",
      gradingScholar = "Shaykh al-Mufid (d. 413 AH), Shaykh al-Tusi & Allama Tabataba'i",
      reference = "Kitab al-Irshad 1:51 • Tarikh al-Ya'qubi 2:38",
      linkedQuranVerses = "2:207, 8:30"
    ),
    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 2,
      bookName = "Book 2: Prophetic Battles — Badr (2 AH), Uhud (3 AH), Khandaq (5 AH) & Khaybar (7 AH)",
      chapterNumber = 1,
      chapterName = "Steadfastness and Valor of Amir al-Mu'minin 'Ali (AS) in the Prophetic Maghazi",
      hadithNumber = 2,
      darussalamReference = "Kitab al-Irshad (Shaykh al-Mufid): Vol. 1, p. 67 (#2)",
      inBookReference = "In-Book: Book 2, Hadith 2 • A'lam al-Wara (Al-Tabarsi) Vol. 1, p. 176 • Bihar al-Anwar Vol. 19",
      arabicNumber = 2,
      arabicText = "لَا فَتَى إِلَّا عَلِيٌّ، وَلَا سَيْفَ إِلَّا ذُو الْفَقَارِ",
      transliteration = "La fata illa 'Ali, wa la sayfa illa Dhul-Faqar.",
      englishText = "Shaykh al-Mufid documents in Kitab al-Irshad (Vol. 1, pp. 67–135) and Shaykh al-Tabarsi in A'lam al-Wara the decisive role of Imam 'Ali ibn Abi Talib (AS) across the Prophetic battles: carrying the banner at Badr (2 AH), defending the Prophet (ﷺ) at Uhud (3 AH) where Jibril proclaimed 'There is no chivalrous youth like 'Ali and no sword like Dhu al-Faqar', meeting 'Amr ibn 'Abd Wudd at the Battle of the Trench (Khandaq, 5 AH) where the Prophet (ﷺ) said 'The strike of 'Ali on the Day of al-Khandaq is superior to the worship of the two weighty creations (al-Thaqalayn)', and opening the fortress of al-Qamus at Khaybar (7 AH).",
      urduText = "شیخ مفید نے ’کتاب الارشاد‘ (جلد 1 ص 67 تا 135) اور شیخ طبرسی نے ’اعلام الوریٰ‘ میں غزواتِ نبوی — غزوہ بدر (2 ہجری)، غزوہ احد (3 ہجری)، غزوہ خندق (5 ہجری) اور غزوہ خیبر (7 ہجری) — میں امیر المومنین حضرت علی علیہ السلام کی استقامت و شجاعت کو تفصیل سے قلمبند کیا ہے؛ غزوہ احد میں ندا آئی: ’لا فتیٰ الا علی لا سیف الا ذوالفقار‘ اور غزوہ خندق میں عمرو بن عبد ود کے مقابلے پر رسول اللہ ﷺ نے فرمایا کہ خندق کے دن علی کی ضربت ثقلین کی عبادت سے افضل ہے۔",
      narrator = "Shaykh al-Mufid, Shaykh al-Tabarsi & Ibn Shahrashub",
      grade = "Authenticated Imami Historical & Hadith Tradition",
      gradingScholar = "Shaykh al-Mufid (Kitab al-Irshad) & Allama al-Majlisi (Bihar al-Anwar)",
      reference = "Kitab al-Irshad 1:67 • A'lam al-Wara 1:176",
      linkedQuranVerses = "33:23, 33:25, 48:29"
