    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 3,
      bookName = "Book 3: Events of Saqifah Bani Sa'idah & Early Caliphate History (11 AH)",
      chapterNumber = 1,
      chapterName = "Burial of the Prophet (ﷺ), Saqifah Bani Sa'idah, and Imam 'Ali's Preservation of Unity",
      hadithNumber = 3,
      darussalamReference = "Tarikh al-Ya'qubi: Vol. 2, p. 123 / Nahj al-Balagha Letter 62 (#3)",
      inBookReference = "In-Book: Book 3, Hadith 3 • Al-Ihtijaj (Al-Tabarsi) Vol. 1, p. 73",
      arabicNumber = 3,
      arabicText = "فَأَمْسَكْتُ يَدِي حَتَّى رَأَيْتُ رَاجِعَةَ النَّاسِ قَدْ رَجَعَتْ عَنِ الْإِسْلَامِ يَدْعُونَ إِلَى مَحْقِ دِينِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ",
      transliteration = "Fa-amsaktu yadi hatta ra'aytu raji'atan-nasi qad raja'at 'anil-Islami yad'una ila mahqi dini Muhammadin (ﷺ).",
      englishText = "In Tarikh al-Ya'qubi (Vol. 2, pp. 123–127) and Nahj al-Balagha (Letter 62 & Sermon 3), following the passing of the Prophet (ﷺ) in 11 AH, while Amir al-Mu'minin 'Ali (AS) and Banu Hashim were engaged in washing and burying the sacred body of the Messenger of Allah (ﷺ), the assembly at Saqifah Bani Sa'idah took place. Imam 'Ali (AS) explained in Letter 62 to the people of Egypt why he exercised patience while preserving his right: 'I withheld my hand until I saw that a group of people were turning back from Islam, calling for the effacement of the religion of Muhammad (ﷺ); so I feared that if I did not assist Islam and its people, I would witness a breach or destruction in it that would be a greater calamity to me than the loss of authority over you.'",
      urduText = "تاریخ یعقوبی (جلد 2 ص 123) اور نہج البلاغہ (مکتوب 62 اور خطبہ 3) میں منقول ہے کہ 11 ہجری میں وصالِ نبوی ﷺ کے وقت جب حضرت علی علیہ السلام اور بنو ہاشم رسول اللہ ﷺ کے غسل و تکفین میں مصروف تھے تو سقیفہ بنی ساعدہ کا اجتماع پیش آیا۔ امیر المومنین علیہ السلام نے اہلِ مصر کے نام اپنے مکتوب (62) میں فرمایا کہ میں نے اپنا ہاتھ روکے رکھا یہاں تک کہ میں نے دیکھا کہ کچھ لوگ اسلام سے پھر رہے ہیں، چنانچہ مجھے اندیشہ ہوا کہ اگر میں اسلام اور اہلِ اسلام کی نصرت نہ کروں تو دین میں ایسا رخنہ واقع ہوگا جس کا صدمہ مجھ پر تمہاری حکومت کے فوت ہو جانے سے کہیں بڑھ کر تھا۔",
      narrator = "Amir al-Mu'minin 'Ali ibn Abi Talib (AS) [Nahj al-Balagha & Tarikh al-Ya'qubi]",
      grade = "Canonical Imami Historical Text",
      gradingScholar = "Al-Sharif al-Radi, Ahmad al-Ya'qubi & Shaykh al-Tabarsi",
      reference = "Tarikh al-Ya'qubi 2:123 • Nahj al-Balagha Letter 62",
      linkedQuranVerses = "3:144, 5:67"
    ),
    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 4,
      bookName = "Book 4: Battle of al-Qadisiyyah & Battle of Yarmouk in Shia Chronicles (14–15 AH)",
      chapterNumber = 1,
      chapterName = "Imam 'Ali's Strategic Counsel and the Role of Hashim al-Mirqal & Malik al-Ashtar at Qadisiyyah & Yarmouk",
      hadithNumber = 4,
      darussalamReference = "Tarikh al-Ya'qubi: Vol. 2, p. 143 / Nahj al-Balagha Sermon 146 (#4)",
      inBookReference = "In-Book: Book 4, Hadith 4 • Kitab al-Futuh (Ibn A'tham al-Kufi) Vol. 1, p. 201",
      arabicNumber = 4,
      arabicText = "إِنَّ هَذَا الْأَمْرَ لَمْ يَكُنْ نَصْرُهُ وَلَا خِذْلَانُهُ بِكَثْرَةٍ وَلَا بِقِلَّةٍ، وَهُوَ دِينُ اللَّهِ الَّذِي أَظْهَرَهُ، وَجُنْدُهُ الَّذِي أَعَزَّهُ وَأَمَدَّهُ",
      transliteration = "Inna hadhal-amra lam yakun nasruhu wa la khidhlanuhu bi-kathratin wa la bi-qillah, wa huwa dinulladhi azharahu wa junduhulladhi a'azzahu wa amaddah.",
      englishText = "In Tarikh al-Ya'qubi (Vol. 2, pp. 139–146), Nahj al-Balagha (Sermon 146), and Kitab al-Futuh of Ibn A'tham al-Kufi (Vol. 1), when 'Umar ibn al-Khattab consulted regarding marching in person to the Battle of al-Qadisiyyah (14–15 AH), Imam 'Ali ibn Abi Talib (AS) advised him to remain as the central axis (Qutb) in Madinah and dispatch the armies, declaring: 'The victory or setback of this cause has never depended on large or small numbers; it is Allah's religion which He has made prevail and His army which He has strengthened.' Shia chronicles highlight the heroic leadership of Hashim ibn 'Utbah al-Mirqal, Malik al-Ashtar al-Nakha'i, Hujr ibn 'Adi al-Kindi, and 'Adi ibn Hatim al-Ta'i at both the Battle of Yarmouk (15 AH) and the Battle of al-Qadisiyyah (14–15 AH).",
      urduText = "تاریخ یعقوبی (جلد 2 ص 139 تا 146)، نہج البلاغہ (خطبہ 146) اور کتاب الفتوح لابن اعثم کوفی میں مذکور ہے کہ معرکہ قادسیہ (14–15 ہجری) کے موقع پر جب مشورہ طلب کیا گیا تو حضرت علی علیہ السلام نے مدینہ کو مرکز (قطب) برقرار رکھنے کا تاریخی مشورہ دیا اور فرمایا: اس امر (اسلام) کی فتح و نصرت کبھی کثرت یا قلت پر موقوف نہیں رہی، بلکہ یہ اللہ کا دین ہے جسے اس نے غالب کیا۔ شیعہ تواریخ میں جنگِ یرموک (15 ہجری) اور جنگِ قادسیہ (14–15 ہجری) میں ہاشم بن عتبہ المرقال، مالک اشتر نخعی، حجر بن عدی کندی اور عدی بن حاتم طائی کے کلیدی کردار کو تفصیل سے بیان کیا گیا ہے۔",
      narrator = "Ahmad al-Ya'qubi, Al-Sharif al-Radi & Ibn A'tham al-Kufi",
      grade = "Verified Classical Historical Chronicle (Nahj al-Balagha & Al-Ya'qubi)",
      gradingScholar = "Al-Sharif al-Radi, Ahmad al-Ya'qubi (d. 284 AH) & Ibn A'tham al-Kufi (d. 314 AH)",
      reference = "Nahj al-Balagha Sermon 146 • Tarikh al-Ya'qubi 2:143",
      linkedQuranVerses = "9:40, 48:28, 61:9"
    ),
    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 5,
      bookName = "Book 5: Battle of Jamal (Waq'at al-Jamal, Basra, 36 AH) & Conduct in Warfare",
      chapterNumber = 1,
      chapterName = "Imam 'Ali's Ethical Rules of Engagement and Dignified Treatment of the Vanquished at Basra",
      hadithNumber = 5,
      darussalamReference = "Kitab al-Jamal (Shaykh al-Mufid): p. 388 / Kitab al-Irshad Vol. 1 (#5)",
      inBookReference = "In-Book: Book 5, Hadith 5 • Nahj al-Balagha Letter 14 • Al-Kafi Vol. 5, p. 38",
      arabicNumber = 5,
      arabicText = "لَا تَتْبَعُوا مُدْبِرًا، وَلَا تُذَفِّفُوا عَلَى جَرِيحٍ، وَمَنْ أَغْلَقَ بَابَهُ فَهُوَ آمِنٌ",
      transliteration = "La tatba'u mudbiran, wa la tudhaffifu 'ala jarihin, wa man aghlaqa babahu fa-huwa amin.",
      englishText = "In Shaykh al-Mufid's Kitab al-Jamal and Kitab al-Irshad (Vol. 1, p. 250), as well as Kitab al-Kafi (Vol. 5, p. 38), at the Battle of Jamal in Basra (Jumada al-Thaniyah 36 AH / 656 CE), Amir al-Mu'minin 'Ali (AS) exhausted every peaceful appeal for reconciliation before battle, and afterward proclaimed the canonical Islamic law of internal conflict (Ahkam Ahl al-Baghy): 'Do not pursue anyone who retreats, do not strike the wounded, do not enter houses, and whoever closes his door is safe,' and he escorted 'A'ishah back to Madinah with full honor and protection.",
      urduText = "شیخ مفید کی ’کتاب الجمل‘ اور ’کتاب الارشاد‘ (جلد 1 ص 250) نیز ’فروع الکافی‘ (جلد 5 ص 38) میں مروی ہے کہ جنگِ جمل (جمادی الثانیہ 36 ہجری / 656ء، بصرہ) میں امیر المومنین حضرت علی علیہ السلام نے جنگ روکنے کی ہر ممکن کوشش فرمائی اور فتح کے بعد تاریخی اسلامی قانون نافذ فرمایا: ’کسی بھاگنے والے کا تعاقب نہ کرو، کسی زخمی پر وار نہ کرو، اور جو اپنا دروازہ بند کر لے وہ امن میں ہے‘، اور حضرت عائشہ کو پورے احترام و حفاظت کے ساتھ مدینہ روانہ فرمایا۔",
      narrator = "Imam Ja'far al-Sadiq (AS) & Shaykh al-Mufid",
      grade = "Sahih (Al-Kafi Vol. 5 & Kitab al-Irshad)",
      gradingScholar = "Shaykh al-Kulayni, Shaykh al-Mufid & Allama al-Majlisi",
      reference = "Al-Kafi 5:38 • Kitab al-Irshad 1:250",
      linkedQuranVerses = "49:9, 49:10"
    ),
    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 6,
      bookName = "Book 6: Battle of Siffin (Waq'at Siffin — وقعة صفين, 37 AH) & Martyrdom of 'Ammar ibn Yasir",
      chapterNumber = 1,
      chapterName = "Liberation of the Euphrates Water, Martyrdom of 'Ammar ibn Yasir, and the Arbitration at Siffin",
      hadithNumber = 6,
      darussalamReference = "Waq'at Siffin (Nasr ibn Muzahim): p. 152 / Kitab al-Irshad Vol. 1 (#6)",
      inBookReference = "In-Book: Book 6, Hadith 6 • Nahj al-Balagha Sermon 51 • Tarikh al-Ya'qubi Vol. 2, p. 188",
      arabicNumber = 6,
      arabicText = "وَيْحَ عَمَّارٍ تَقْتُلُهُ الْفِئَةُ الْبَاغِيَةُ، يَدْعُوهُمْ إِلَى الْجَنَّةِ وَيَدْعُونَهُ إِلَى النَّارِ",
      transliteration = "Wayha 'Ammarin taqtuluhul-fi'atul-baghiyah, yad'uhum ilal-Jannati wa yad'unahu ilan-Nar.",
      englishText = "In Waq'at Siffin by Nasr ibn Muzahim al-Minqari (d. 212 AH), Kitab al-Irshad by Shaykh al-Mufid (Vol. 1, p. 255), and Nahj al-Balagha (Sermon 51), when Mu'awiyah's forces seized the Euphrates river at Siffin (37 AH / 657 CE) to deny water to Imam 'Ali's army, Malik al-Ashtar and Ash'ath ibn Qays dislodged them, whereupon Imam 'Ali (AS) forbade denying water to the Syrian army. During the battle, the ninety-three-year-old Companion 'Ammar ibn Yasir (RA/AS) was martyred, fulfilling the universally transmitted Prophetic Hadith: 'Alas for 'Ammar! The rebellious faction (al-fi'ah al-baghiyah) will kill him; he calls them to Paradise and they call him to the Fire.'",
      urduText = "نصر بن مزاحم منقری (متوفی 212 ہجری) کی تاریخی کتاب ’وقعۃ صفین‘، شیخ مفید کی ’کتاب الارشاد‘ (جلد 1 ص 255) اور نہج البلاغہ (خطبہ 51) میں معرکہ صفین (37 ہجری / 657ء) کی تفصیلات درج ہیں: جب شامی لشکر نے دریائے فرات کے پانی پر قبضہ کیا تو مالک اشتر نے گزرگاہ آزاد کرائی، مگر امیر المومنین حضرت علی علیہ السلام نے دشمن پر پانی بند کرنے سے منع فرمایا۔ اسی معرکے میں جلیل القدر صحابی حضرت عمار بن یاسرؓ کی شہادت ہوئی جس کے بارے میں متواتر حدیثِ نبوی ﷺ تھی کہ ’عمار کو باغی گروہ قتل کرے گا‘۔",
      narrator = "Nasr ibn Muzahim al-Minqari (Waq'at Siffin), Shaykh al-Mufid & Al-Sharif al-Radi",
      grade = "Mutawatir Hadith & Primary 3rd-Century Historical Monograph",
      gradingScholar = "Nasr ibn Muzahim (d. 212 AH), Shaykh al-Mufid & Allama al-Amini",
      reference = "Waq'at Siffin p. 152 • Kitab al-Irshad 1:255",
      linkedQuranVerses = "49:9, 28:5"
    ),
    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 7,
      bookName = "Book 7: Battle of Nahrawan (38 AH) & Martyrdom of Imam 'Ali (AS) in Kufa (Ramadan 40 AH)",
      chapterNumber = 1,
      chapterName = "Confronting the Khawarij at Nahrawan and the Final Testament of Imam 'Ali (AS)",
      hadithNumber = 7,
      darussalamReference = "Kitab al-Irshad (Shaykh al-Mufid): Vol. 1, p. 14 / Nahj al-Balagha Letter 47 (#7)",
      inBookReference = "In-Book: Book 7, Hadith 7 • Tarikh al-Ya'qubi Vol. 2, p. 212",
      arabicNumber = 7,
      arabicText = "كَلِمَةُ حَقٍّ يُرَادُ بِهَا بَاطِلٌ ... أُوصِيكُمَا بِتَقْوَى اللَّهِ، وَأَلَّا تَبْغِيَا الدُّنْيَا وَإِنْ بَغَتْكُمَا",
      transliteration = "Kalimatu haqqin yuradu biha batil... Usikuma bi-taqwallahi, wa alla tabghiyad-dunya wa in baghatkuma.",
      englishText = "In Kitab al-Irshad (Vol. 1) and Nahj al-Balagha (Sermon 40 & Letter 47), when the Khawarij raised the slogan 'No judgment except Allah's' to reject legitimate governance, Imam 'Ali (AS) replied with the immortal dictum: 'A word of truth by which falsehood is intended!' After sending Ibn 'Abbas to debate them and thousands returned peacefully, he defeated the armed insurgents who had murdered 'Abdullah ibn Khabbab at the Battle of Nahrawan (38 AH). Struck in the mihrab of the Great Mosque of Kufa on 19 Ramadan 40 AH (661 CE), he bequeathed to al-Hasan and al-Husayn (AS) in Letter 47: 'I advise you both to have Taqwa of Allah, to uphold reconciliation, to care for orphans and neighbors, and to forbid retaliation beyond justice.'",
      urduText = "شیخ مفید کی ’کتاب الارشاد‘ (جلد 1) اور نہج البلاغہ (خطبہ 40 اور وصیت نامہ مکتوب 47) میں معرکہ نہروان (38 ہجری) اور شہادتِ امیر المومنین علیہ السلام (21 رمضان 40 ہجری، مسجدِ کوفہ) کا بیان ہے: خوارج کے نعرے پر آپؑ نے فرمایا ’کلمۃ حق یراد بہا باطل‘ (بات سچی ہے مگر اس سے مراد باطل لی جا رہی ہے)، اور اتمامِ حجت کے بعد نہروان میں خوارج کے فتنے کا سدباب کیا۔ ضربت لگنے کے بعد امام حسن اور امام حسین علیہما السلام کو تقویٰ، اصلاحِ ذات البین، یتیموں اور ہمسایوں کے حقوق اور عدل کی وصیت فرمائی۔",
      narrator = "Shaykh al-Mufid (Kitab al-Irshad) & Al-Sharif al-Radi (Nahj al-Balagha)",
      grade = "Sahih & Mutawatir Imami Historical Testament",
      gradingScholar = "Shaykh al-Mufid, Al-Sharif al-Radi & Shaykh al-Kulayni (Al-Kafi Vol. 7)",
      reference = "Nahj al-Balagha Letter 47 • Kitab al-Irshad 1:14",
      linkedQuranVerses = "47:7, 2:178, 8:1"
    ),
    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 8,
      bookName = "Book 8: Imamate & Peace Treaty of Imam al-Hasan al-Mujtaba (AS) (40–50 AH)",
      chapterNumber = 1,
      chapterName = "The Terms of the Peace Treaty of 41 AH to Preserve the Blood of the Muslims",
      hadithNumber = 8,
      darussalamReference = "Kitab al-Irshad (Shaykh al-Mufid): Vol. 2, p. 8 (#8)",
      inBookReference = "In-Book: Book 8, Hadith 8 • Tarikh al-Ya'qubi Vol. 2, p. 215 • Bihar al-Anwar Vol. 44",
      arabicNumber = 8,
      arabicText = "إِنِّي خَشِيتُ أَنْ يُجْتَثَّ الْمُسْلِمُونَ عَنْ وَجْهِ الْأَرْضِ فَأَرَدْتُ أَنْ يَكُونَ لِلدِّينِ فِي الْأَرْضِ نَاعٍ",
      transliteration = "Inni khashitu an yujtaththal-Muslimuna 'an wajhil-ardi fa-aradtu an yakuna lid-dini fil-ardi na'in.",
      englishText = "In Shaykh al-Mufid's Kitab al-Irshad (Vol. 2, pp. 8–16) and Tarikh al-Ya'qubi (Vol. 2, p. 215), in 41 AH (661 CE), Imam al-Hasan ibn 'Ali al-Mujtaba (AS) concluded the Conditional Treaty of Peace to prevent the annihilation of the faithful and stipulated: acting according to the Book of Allah and the Sunnah of His Prophet (ﷺ), cessation of cursing Amir al-Mu'minin 'Ali (AS), security for the companions and followers of 'Ali, and that Mu'awiyah had no right to appoint a successor after himself.",
      urduText = "شیخ مفید کی ’کتاب الارشاد‘ (جلد 2 ص 8 تا 16) اور ’تاریخ یعقوبی‘ (جلد 2 ص 215) میں 41 ہجری میں حضرت امام حسن مجتبیٰ علیہ السلام کے صلح نامے کی شرائط محفوظ ہیں: آپؑ نے مسلمانوں کے خون کی حفاظت کے لیے کتاب اللہ اور سنتِ رسول اللہ ﷺ پر عمل، امیر المومنین حضرت علیؑ اور آپ کے اصحاب کے جان و مال کے تحفظ، اور معاویہ کے بعد کسی جانشین کی نامزدگی نہ ہونے کی شرائط پر معاہدہ فرمایا۔",
      narrator = "Shaykh al-Mufid (Kitab al-Irshad) & Ahmad al-Ya'qubi",
      grade = "Authenticated Imami Historical Account",
