    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 9,
      bookName = "Book 9: Event of Karbala & Martyrdom of Imam al-Husayn (AS) ('Ashura, 10 Muharram 61 AH)",
      chapterNumber = 1,
      chapterName = "Imam al-Husayn's (AS) Proclamation of Reform and the Epic of Karbala",
      hadithNumber = 9,
      darussalamReference = "Kitab al-Irshad (Shaykh al-Mufid): Vol. 2, p. 32 / Al-Luhuf (#9)",
      inBookReference = "In-Book: Book 9, Hadith 9 • Maqtal Abi Mikhnaf • Bihar al-Anwar Vol. 44, p. 329",
      arabicNumber = 9,
      arabicText = "إِنِّي لَمْ أَخْرُجْ أَشِرًا وَلَا بَطِرًا وَلَا مُفْسِدًا وَلَا ظَالِمًا، وَإِنَّمَا خَرَجْتُ لِطَلَبِ الْإِصْلَاحِ فِي أُمَّةِ جَدِّي، أُرِيدُ أَنْ آمُرَ بِالْمَعْرُوفِ وَأَنْهَى عَنِ الْمُنْكَرِ",
      transliteration = "Inni lam akhruj ashiran wa la batiran wa la mufsidan wa la zaliman, wa innama kharajtu li-talabil-islahi fi ummati jaddi, uridu an amura bil-ma'rufi wa anha 'anil-munkar.",
      englishText = "In Shaykh al-Mufid's Kitab al-Irshad (Vol. 2, pp. 32–135), Sayyid Ibn Tawus's Al-Luhuf 'ala Qatla al-Tufuf, and Tarikh al-Ya'qubi (Vol. 2, p. 241), when departing Madinah in 60 AH, Imam al-Husayn ibn 'Ali (AS) wrote in his testament to his brother Muhammad ibn al-Hanafiyyah: 'Indeed, I have not risen out of insolence, arrogance, corruption, or oppression; rather, I have risen only to seek reform (Islah) in the Ummah of my Grandfather (ﷺ): I desire to enjoin what is right and forbid what is wrong, and to walk in the way of my Grandfather and my father 'Ali ibn Abi Talib.' On 10 Muharram 61 AH ('Ashura) at Karbala, Imam al-Husayn (AS), 'Abbas ibn 'Ali, 'Ali al-Akbar, and the faithful companions gave their lives refusing allegiance to tyranny.",
      urduText = "شیخ مفید کی ’کتاب الارشاد‘ (جلد 2 ص 32 تا 135)، سید ابن طاؤس کی ’اللہوف علی قتلی الطفوف‘ اور ’بحار الانوار‘ (جلد 44 ص 329) میں سید الشہداء حضرت امام حسین علیہ السلام کا تاریخی وصیت نامہ منقول ہے: ’میں ہرگز خود سری، تکبر، فساد یا ظلم کے لیے نہیں نکلا، بلکہ میں صرف اپنے نانا رسول اللہ ﷺ کی امت کی اصلاح کے لیے نکلا ہوں؛ میں نیکی کا حکم دینا اور برائی سے روکنا چاہتا ہوں اور اپنے نانا ﷺ اور اپنے بابا علی بن ابی طالبؑ کی سیرت پر چلنا چاہتا ہوں۔‘ دس محرم 61 ہجری (یومِ عاشورہ) کو میدانِ کربلا میں آپؑ اور آپ کے اصحاب و بنی ہاشم نے باطل کی بیعت سے انکار کرتے ہوئے جامِ شہادت نوش فرمایا۔",
      narrator = "Imam al-Husayn ibn 'Ali (AS) [Kitab al-Irshad, Al-Luhuf & Bihar al-Anwar]",
      grade = "Mutawatir & Foundational Shia Historical Account",
      gradingScholar = "Shaykh al-Mufid (d. 413 AH), Sayyid Ibn Tawus (d. 664 AH) & Allama al-Majlisi",
      reference = "Kitab al-Irshad 2:32 • Bihar al-Anwar 44:329",
      linkedQuranVerses = "3:104, 33:23, 89:27, 89:28"
    ),
    HadithEntity(
      collectionKey = "shia_history",
      collectionName = "History of Islam — Shia Chronicles",
      bookNumber = 10,
      bookName = "Book 10: Waqia Harrah — The Battle of al-Harrah in Madinah (Waq'at al-Harrah — وقعة الحرة, 63 AH)",
      chapterNumber = 1,
      chapterName = "Waqia Hurrah (63 AH) in Shia Chronicles and Imam Zayn al-'Abidin's (AS) Protection of Madinah's Families",
      hadithNumber = 10,
      darussalamReference = "Kitab al-Irshad (Shaykh al-Mufid): Vol. 2, p. 149 / Tarikh al-Ya'qubi Vol. 2, p. 250 (#10)",
      inBookReference = "In-Book: Book 10, Hadith 10 • Muruj al-Dhahab (Al-Mas'udi) Vol. 3, p. 69 • Bihar al-Anwar Vol. 46, p. 110",
      arabicNumber = 10,
      arabicText = "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مُسْلِمِ بْنِ عُقْبَةَ ... فَضَمَّ عَلِيُّ بْنُ الْحُسَيْنِ أَرْبَعَمِائَةِ امْرَأَةٍ وَعِيَالَهُنَّ إِلَى دَارِهِ يُنْفِقُ عَلَيْهِنَّ",
      transliteration = "Allahumma inni a'udhu bika min sharri Muslimi bni 'Uqbah... Fa-damma 'Aliyyu bnu al-Husayni arba'a mi'ati imra'atin wa 'iyalahunna ila darihi yunfiqu 'alayhinna.",
      englishText = "Waqia Harrah / Battle of al-Harrah (Waq'at al-Harrah — وقعة الحرة, Dhu al-Hijjah 63 AH / 683 CE) in Shia Chronicles: Ahmad al-Ya'qubi (Tarikh al-Ya'qubi Vol. 2, pp. 250–252), Al-Mas'udi (Muruj al-Dhahab Vol. 3, p. 69), and Shaykh al-Mufid (Kitab al-Irshad Vol. 2, p. 149) record that when Yazid ibn Mu'awiyah sent Muslim ibn 'Uqbah (whom the early historians called 'Musrif') against Madinah at the Battle of al-Harrah, the Syrian army slaughtered the Ansar, Muhajirun, and children of the Companions and pillaged Madinah for three days. During this crisis, Imam 'Ali ibn al-Husayn Zayn al-'Abidin (AS) sheltered four hundred families of Madinah—including the household of Marwan ibn al-Hakam—in his own home, sharing his provisions with them until the army departed.",
      urduText = "واقعہ حرہ (معرکہ حرہ / وقعة الحرة، ذوالحجہ 63 ہجری / 683ء) شیعہ مآخذ میں: احمد یعقوبی کی ’تاریخ یعقوبی‘ (جلد 2 ص 250)، مسعودی کی ’مروج الذہب‘ (جلد 3 ص 69) اور شیخ مفید کی ’کتاب الارشاد‘ (جلد 2 ص 149) نیز ’بحار الانوار‘ (جلد 46 ص 110) میں درج ہے کہ جب یزید بن معاویہ نے مسلم بن عقبہ کو مدینہ منورہ پر چڑھائی کے لیے بھیجا اور واقعہ حرہ پیش آیا جس میں انصار و مہاجرین اور فرزندانِ صحابہ شہید ہوئے اور تین روز تک مدینہ منورہ کو لوٹا گیا، تو اس کٹھن گھڑی میں حضرت امام زین العابدین علی بن الحسین علیہ السلام نے مدینہ کے چار سو خاندانوں کو اپنے گھر میں پناہ دی اور ان کے طعام و کفالت کا انتظام فرمایا۔",
      narrator = "Shaykh al-Mufid (Kitab al-Irshad), Ahmad al-Ya'qubi & Al-Mas'udi",
      grade = "Verified Classical Shia Historical Account (Waq'at al-Harrah 63 AH)",
      gradingScholar = "Shaykh al-Mufid (d. 413 AH), Ahmad al-Ya'qubi (d. 284 AH) & Allama al-Majlisi",
      reference = "Kitab al-Irshad 2:149 • Tarikh al-Ya'qubi 2:250 • Bihar al-Anwar 46:110",
      linkedQuranVerses = "76:8, 76:9, 33:60"
    ),

