      inBookReference = "In-Book: Jild 5, Kitab al-Du'a, Bab 1, Hadith 1",
      arabicNumber = 501,
      arabicText = "الدُّعَاءُ سِلَاحُ الْمُؤْمِنِ، وَعَمُودُ الدِّينِ، وَنُورُ السَّمَاوَاتِ وَالْأَرْضِ. وَقَالَ أَبُو عَبْدِ اللَّهِ عَلَيْهِ السَّلَامُ: إِنَّ الدُّعَاءَ يَرُدُّ الْقَضَاءَ وَقَدْ نَزَلَ مِنَ السَّمَاءِ وَقَدْ أُبْرِمَ إِبْرَامًا",
      transliteration = "Ad-du'a'u silahul-mu'min, wa 'amudud-din, wa nurus-samawati wal-ard. Wa qala Abu 'Abdillah (AS): Innad-du'a'a yaruddul-qada'a wa qad nazala minas-sama'i wa qad ubrima ibrama.",
      englishText = "The Messenger of Allah (ﷺ) said: 'Supplication (Du'a) is the weapon of the believer, the pillar of religion, and the light of the heavens and the earth.' And Imam Ja'far al-Sadiq (AS) said: 'Indeed, supplication turns back the decree even after it has descended from heaven and been firmly ratified.'",
      urduText = "رسول اللہ ﷺ نے فرمایا: دعا مومن کا ہتھیار، دین کا ستون اور آسمانوں اور زمین کا نور ہے۔ اور امام جعفر صادق علیہ السلام نے فرمایا: بے شک دعا اس قضا کو بھی ٹال دیتی ہے جو آسمان سے نازل ہو کر پختہ ہو چکی ہو۔ (الکافی جلد 2 / حصہ پنجم، کتاب الدعا)۔",
