      darussalamReference = "Al-Kafi: Vol. 2 (Jild 6), p. 596 (#601)",
      inBookReference = "In-Book: Jild 6, Kitab Fadl al-Qur'an, Bab 1, Hadith 1",
      arabicNumber = 601,
      arabicText = "الْقُرْآنُ عَهْدُ اللَّهِ إِلَى خَلْقِهِ، فَقَدْ يَنْبَغِي لِلْمَرْءِ الْمُسْلِمِ أَنْ يَنْظُرَ فِي عَهْدِهِ وَأَنْ يَقْرَأَ مِنْهُ فِي كُلِّ يَوْمٍ خَمْسِينَ آيَةً",
      transliteration = "Al-Qur'anu 'ahdullahi ila khalqihi, faqad yanbaghi lil-mar'il-muslimi an yanzura fi 'ahdihi wa an yaqra'a minhu fi kulli yawmin khamsina ayah.",
      englishText = "Imam Ja'far al-Sadiq (AS) said: 'The Quran is the covenant of Allah to His creation; therefore, it befits a Muslim person to look into His covenant and recite fifty verses from it every day.'",
      urduText = "امام جعفر صادق علیہ السلام نے فرمایا: قرآن اللہ تعالیٰ کا اپنی مخلوق کی طرف عہد نامہ ہے، پس ہر مسلمان کو چاہیے کہ وہ اپنے رب کے عہد نامے میں نظر کرے اور روزانہ کم از کم پچاس آیتیں اس کی تلاوت کرے۔ (الکافی، کتاب فضل القرآن، ص 596)۔",
