      darussalamReference = "Furu' al-Kafi: Vol. 5 (Jild 7), p. 78 (#701)",
      inBookReference = "In-Book: Jild 7, Furu' al-Kafi, Kitab al-Ma'ishah, Hadith 1",
      arabicNumber = 701,
      arabicText = "الْكَادُّ عَلَى عِيَالِهِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ. وَقَالَ أَبُو عَبْدِ اللَّهِ عَلَيْهِ السَّلَامُ: تَرْكُ لُقْمَةِ حَرَامٍ أَحَبُّ إِلَى اللَّهِ عَزَّ وَجَلَّ مِنْ صَلَاةِ أَلْفَيْ رَكْعَةٍ تَطَوُّعًا",
      transliteration = "Al-kaddu 'ala 'iyalihi kal-mujahidi fi sabilillah. Wa qala Abu 'Abdillah (AS): Tarku luqmati haramin ahabbu ilallahi 'azza wa jalla min salati alfay rak'atin tatawwu'a.",
      englishText = "Imam Musa al-Kazim (AS) and Imam Ja'far al-Sadiq (AS) narrated: 'One who strives hard to earn lawful provision for his family is like one who strives in the way of Allah.' And Imam al-Sadiq (AS) said: 'Abandoning a single morsel of the unlawful (Haram) is more beloved to Allah the Mighty and Majestic than two thousand rak'ahs of supererogatory prayer.'",
      urduText = "فروع الکافی میں امام جعفر صادق اور امام موسیٰ کاظم علیہما السلام سے مروی ہے: اپنے اہل و عیال کے لیے حلال روزی کمانے کی محنت کرنے والا اللہ کی راہ میں جہاد کرنے والے کی مانند ہے، اور حرام کا ایک لقمہ چھوڑ دینا اللہ عزوجل کے نزدیک دو ہزار نفل رکعتوں سے زیادہ محبوب ہے۔ (فروع الکافی جلد 5 ص 78)۔",
      narrator = "Imam Ja'far al-Sadiq (AS) & Imam Musa al-Kazim (AS)",
      grade = "Sahih",
      gradingScholar = "Allama al-Majlisi (Mir'at al-'Uqul 18:302)",
      reference = "Furu' al-Kafi 5:78",
      linkedQuranVerses = "2:168, 2:172, 62:10"
    ),
    HadithEntity(
      collectionKey = "alkafi",
      collectionName = "Al-Kafi (Usul, Furu' & Rawdah)",
      bookNumber = 8,
      bookName = "Jild 8: Rawdat al-Kafi — Sermons, Letters & Hadith al-Manzilah (روضة الكافي)",
      chapterNumber = 1,
      chapterName = "Khutbat al-Muttaqin, Prophetic Counsels & Hadith al-Manzilah in Rawdat al-Kafi",
      hadithNumber = 801,
      darussalamReference = "Rawdat al-Kafi: Vol. 8 (Jild 8), p. 107 (#801)",
      inBookReference = "In-Book: Jild 8, Rawdat al-Kafi, Hadith 107",
      arabicNumber = 801,
      arabicText = "أَنْتَ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى إِلَّا أَنَّهُ لَا نَبِيَّ بَعْدِي. وَقَالَ عَلَيْهِ السَّلَامُ: أَحِبُّوا اللَّهَ لِمَا يَغْذُوكُمْ بِهِ مِنْ نِعَمِهِ، وَأَحِبُّونِي لِحُبِّ اللَّهِ، وَأَحِبُّوا أَهْلَ بَيْتِي لِحُبِّي",
      transliteration = "Anta minni bi-manzilati Haruna min Musa illa annahu la nabiyya ba'di. Wa qala (ﷺ): Ahibbullaha lima yaghdukum bihi min ni'amihi, wa ahibbuni li-hubbillah, wa ahibbu Ahla Bayti li-hubbi.",
      englishText = "In Rawdat al-Kafi (Vol. 8, p. 107), the Messenger of Allah (ﷺ) said to 'Ali ibn Abi Talib (AS): 'You are to me at the station of Aaron (Harun) to Moses (Musa), except that there is no Prophet after me.' And the Prophet (ﷺ) said: 'Love Allah for the blessings with which He nourishes you, love me for the love of Allah, and love my Ahl al-Bayt for love of me.'",
      urduText = "روضۃ الکافی (جلد 8 ص 107) میں مروی ہے کہ رسول اللہ ﷺ نے حضرت علی ابن ابی طالب علیہ السلام سے فرمایا: تم کو مجھ سے وہی منزلت حاصل ہے جو ہارونؑ کو موسیٰؑ سے تھی، سوائے اس کے کہ میرے بعد کوئی نبی نہیں۔ اور فرمایا: اللہ سے محبت کرو اس کی ان نعمتوں کی وجہ سے جو وہ تمہیں عطا فرماتا ہے، اور اللہ کی محبت کی خاطر مجھ سے محبت کرو اور میری محبت کی خاطر میرے اہلِ بیت سے محبت کرو۔",
      narrator = "Imam Muhammad al-Baqir (AS) & Imam Ja'far al-Sadiq (AS)",
      grade = "Sahih / Mutawatir",
      gradingScholar = "Shaykh al-Kulayni & Allama al-Majlisi (Mir'at al-'Uqul 26:112)",
      reference = "Rawdat al-Kafi 8:107",
      linkedQuranVerses = "20:29, 42:23, 33:33"
    ),

    // ==================== COMPLETE MAN LA YAHDURUHU AL-FAQIH JILDS 3 TO 4 ====================
    HadithEntity(
      collectionKey = "faqih",
      collectionName = "Man La Yahduruhu al-Faqih",
      bookNumber = 3,
      bookName = "Jild 3: Kitab al-Ma'ishah, Tijarah, Qada' & Nikah (المجلد الثالث: القضاء والمعيشة والنكاح)",
      chapterNumber = 1,
      chapterName = "Justice in Judgment, Honest Trade, and Mercy in Family Life",
      hadithNumber = 301,
      darussalamReference = "Man La Yahduruhu al-Faqih: Vol. 3 (Jild 3), p. 388 (#301)",
      inBookReference = "In-Book: Jild 3, Bab Husn al-Mu'asharah, Hadith 4362",
      arabicNumber = 301,
      arabicText = "خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ، وَأَنَا خَيْرُكُمْ لِأَهْلِي. وَقَالَ الصَّادِقُ عَلَيْهِ السَّلَامُ: رَحِمَ اللَّهُ عَبْدًا أَحْسَنَ فِيمَا بَيْنَهُ وَبَيْنَ زَوْجَتِهِ",
      transliteration = "Khayrukum khayrukum li-ahlihi, wa ana khayrukum li-ahli. Wa qala as-Sadiq (AS): Rahimahullahu 'abdan ahsana fima baynahu wa bayna zawjatih.",
      englishText = "In Man La Yahduruhu al-Faqih (Jild 3, p. 388), the Messenger of Allah (ﷺ) said: 'The best of you is the one who is best to his family, and I am the best of you to my family.' And Imam Ja'far al-Sadiq (AS) said: 'May Allah have mercy upon a servant who acts with kindness and excellence between himself and his spouse.'",
      urduText = "من لا یحضرہ الفقیہ (جلد سوم، ص 388) میں شیخ صدوق روایت کرتے ہیں کہ رسول اللہ ﷺ نے فرمایا: تم میں سب سے بہترین شخص وہ ہے جو اپنے اہل و عیال کے لیے سب سے بہتر ہو، اور میں اپنے اہل و عیال کے لیے تم سب سے بہتر ہوں۔ اور امام جعفر صادق علیہ السلام نے فرمایا: اللہ اس بندے پر رحم فرمائے جو اپنی اہلیہ کے ساتھ حسنِ سلوک سے پیش آتا ہے۔",
      narrator = "Imam Ja'far al-Sadiq (AS) from the Prophet (ﷺ)",
