      urduText = "الاستبصار (جلد سوم، ص 69) میں شیخ طوسی معاملات کی احادیث کی تطبیق کرتے ہوئے رسول اللہ ﷺ اور ائمہ اہلِ بیت علیہم السلام کا اصول نقل فرماتے ہیں: کسی مسلمان کا مال اس کی دلی رضامندی کے بغیر حلال نہیں، اور خرید و فروخت باہمی رضامندی سے ہی معتبر ہے۔",
