      collectionName = "Bihar al-Anwar (Allama al-Majlisi)",
      bookNumber = 1,
      bookName = "Jild 1 (Vol. 37): Kitab al-Imamah — Hadith al-Ghadir & Hadith al-Kisa",
      chapterNumber = 1,
      chapterName = "Proclamation of Ghadir Khumm (18 Dhu al-Hijjah 10 AH) & Hadith al-Kisa",
      hadithNumber = 101,
      darussalamReference = "Bihar al-Anwar: Vol. 37, p. 108 (#101)",
      inBookReference = "In-Book: Vol. 37, Bab Mawla 'Ali & Hadith al-Kisa, Hadith 101",
      arabicNumber = 101,
      arabicText = "أَلَسْتُ أَوْلَى بِكُمْ مِنْ أَنْفُسِكُمْ؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ. قَالَ: فَمَنْ كُنْتُ مَوْلَاهُ فَهَذَا عَلِيٌّ مَوْلَاهُ، اللَّهُمَّ وَالِ مَنْ وَالَاهُ وَعَادِ مَنْ عَادَاهُ وَانْصُرْ مَنْ نَصَرَهُ وَاخْذُلْ مَنْ خَذَلَهُ",
      transliteration = "Alastu awla bikum min anfusikum? Qalu: Bala ya Rasulallah. Qala: Faman kuntu mawlahu fahadha 'Aliyyun mawlahu, Allahumma wali man walahu wa 'adi man 'adahu wansur man nasarahu wakhdhul man khadhalah.",
      englishText = "In Bihar al-Anwar (Vol. 37, p. 108), on 18 Dhu al-Hijjah 10 AH at Ghadir Khumm after the Farewell Pilgrimage, the Messenger of Allah (ﷺ) asked the assembled companions: 'Do I not have more authority over you than you have over yourselves?' They replied: 'Yes, O Messenger of Allah!' Raising the hand of 'Ali ibn Abi Talib (AS), he proclaimed: 'For whomever I am his Mawla (master and leader), this 'Ali is his Mawla. O Allah, be a guardian-friend to whoever befriends him, oppose whoever opposes him, aid whoever aids him, and forsake whoever forsakes him.'",
      urduText = "بحار الانوار (جلد 37، ص 108) میں حجۃ الوداع سے واپسی پر 18 ذوالحجہ 10 ہجری کو غدیرِ خم کے میدان میں رسول اللہ ﷺ کا متواتر اعلان مروی ہے: ’کیا میں تم پر تمہاری جانوں سے زیادہ حق و اختیار نہیں رکھتا؟‘ سب نے عرض کیا: کیوں نہیں یا رسول اللہ! آپ ﷺ نے حضرت علی علیہ السلام کا ہاتھ بلند کر کے فرمایا: ’جس کا میں مولا ہوں اس کے یہ علی مولا ہیں۔ اے اللہ! جو علی کو دوست رکھے تو اسے دوست رکھ، جو ان سے عداوت رکھے تو اس سے عداوت رکھ اور جو ان کی نصرت کرے تو اس کی نصرت فرما۔‘",
      narrator = "Over 110 Companions & Ahl al-Bayt (AS) [Mutawatir]",
      grade = "Mutawatir (Mass-Transmitted)",
      gradingScholar = "Allama al-Majlisi (Bihar al-Anwar) & Allama al-Amini (Al-Ghadir)",
      reference = "Bihar al-Anwar 37:108",
      linkedQuranVerses = "5:67, 5:3, 5:55"
    ),
    HadithEntity(
      collectionKey = "bihar",
      collectionName = "Bihar al-Anwar (Allama al-Majlisi)",
      bookNumber = 1,
      bookName = "Jild 1 (Vol. 35): Ahl al-Bayt & Hadith al-Kisa (حديث الكساء والآية التطهير)",
      chapterNumber = 2,
      chapterName = "The Event of the Cloak (Hadith al-Kisa) and Revelation of the Verse of Purification (33:33)",
      hadithNumber = 102,
      darussalamReference = "Bihar al-Anwar: Vol. 35, p. 206 (#102)",
      inBookReference = "In-Book: Vol. 35, Bab Ayah al-Tathir, Hadith 102",
      arabicNumber = 102,
      arabicText = "اللَّهُمَّ إِنَّ هَؤُلَاءِ أَهْلُ بَيْتِي وَخَاصَّتِي وَحَامَّتِي، لَحْمُهُمْ لَحْمِي وَدَمُهُمْ دَمِي، يُؤْلِمُنِي مَا يُؤْلِمُهُمْ وَيَحْزُنُنِي مَا يَحْزُنُهُمْ... فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا",
      transliteration = "Allahumma inna ha'ula'i Ahlu Bayti wa khassati wa hammati, lahmuhum lahmi wa damuhum dami... Fa-anzalallahu 'azza wa jalla: Innama yuridullahu li-yudhhiba 'ankumur-rijsa Ahlal-Bayti wa yutahhirakum tathira.",
      englishText = "In Bihar al-Anwar (Vol. 35, p. 206), Lady Fatimah al-Zahra (SA) and Jabir ibn 'Abdillah al-Ansari narrate Hadith al-Kisa: The Messenger of Allah (ﷺ) gathered 'Ali, Fatimah, al-Hasan, and al-Husayn (AS) under the Yemeni cloak and supplicated: 'O Allah, these are my Ahl al-Bayt and my closest ones; their flesh is my flesh and their blood is my blood; whatever pains them pains me and whatever grieves them grieves me.' Thereupon Allah revealed Surah al-Ahzab 33:33: 'Indeed, Allah desires only to remove all impurity from you, O People of the Household (Ahl al-Bayt), and to purify you with a thorough purification.'",
      urduText = "بحار الانوار (جلد 35، ص 206) میں سیدہ فاطمہ زہرا سلام اللہ علیہا اور حضرت جابر بن عبداللہ انصاری سے حدیثِ کساء مروی ہے کہ رسول اللہ ﷺ نے حضرت علی، سیدہ فاطمہ، امام حسن اور امام حسین علیہم السلام کو یمنی چادر کے نیچے جمع فرما کر دعا کی: ’اے اللہ! یہ میرے اہلِ بیت اور میرے خاص لوگ ہیں، ان کا گوشت میرا گوشت اور ان کا خون میرا خون ہے، جو چیز انہیں دکھ دیتی ہے وہ مجھے دکھ دیتی ہے۔‘ اس موقع پر آیتِ تطہیر (سورۃ الاحزاب 33:33) نازل ہوئی۔",
      narrator = "Sayyidah Fatimah al-Zahra (SA) & Jabir ibn 'Abdillah al-Ansari",
      grade = "Sahih / Mutawatir",
      gradingScholar = "Allama al-Majlisi, Shaykh al-Tusi & Allama Tabataba'i",
      reference = "Bihar al-Anwar 35:206",
